window.W2W_BUNDLE={"BUILD_ID.js":"// 构建指纹：回归脚本校验用（tools/regression.js）\nmodule.exports = 'BUILD-1105-1007-r6';\n","app.js":"/* 全局入口：状态恢复 + 登录态预热 + 错误上报 */\nconst BUILD_ID = require('./BUILD_ID.js');\nconst auth = require('./services/auth');\nconst CLOUD_ENV = 'cloudbase-d3giwlyte87aecc2e';\n\nApp({\n  BUILD_ID,\n  globalData: { justEntered: false },\n  onLaunch() {\n    /* 云开发初始化：接口层经 wx.cloud.callFunction 直连云函数，身份由云端上下文提供 */\n    if (wx.cloud) {\n      try {\n        wx.cloud.init({ env: CLOUD_ENV, traceUser: true });\n      } catch (e) {\n        reportErr('launch-cloud: ' + e.message);\n      }\n    }\n    /* 登录态预热：接口层未切云端时走本地 mock，切云端后为直通 */\n    auth.ensureSession().catch(err => {\n      reportErr('launch-auth: ' + err.message);\n    });\n    /* 静默同步：问卷档案 + 心情历史（失败不影响进入） */\n    require('./utils/api').syncCloud().catch(() => {});\n  },\n  onError(msg) {\n    reportErr('app-error: ' + msg);\n  },\n  onUnhandledRejection(res) {\n    reportErr('unhandled: ' + (res.reason && res.reason.message || res.reason));\n  }\n});\n\n/* 最小日志上报：真实前端接 wx.getRealtimeLogManager 或自建日志接口 */\nfunction reportErr(msg) {\n  try {\n    wx.getRealtimeLogManager ? wx.getRealtimeLogManager().error(msg) : null;\n  } catch (e) {}\n  console.error(msg);\n}\n","behaviors/frame.js":"/* 页面骨架 behavior：把设备实测的上下留白注入页面。\n * 页面根节点用 --frame-top / --frame-bottom；固定顶栏用 frameStatus + frameNav。\n * ⚠️ 生命周期钩子在页面 behaviors 里不可依赖（实测 onLoad 不执行，见票 30）——\n * 本 behavior 只提供 syncFrame() 方法，各页面在自己 onLoad 里显式调用\n * this.syncFrame()（同 COMPAT 规则 12 的 tab.js 惯例）。 */\nconst ui = require('../utils/ui');\n\nmodule.exports = Behavior({\n  data: { frameTop: 0, frameBottom: 0, frameStatus: 0, frameNav: 0, frameBar: 0 },\n  methods: {\n    syncFrame() {\n      const f = ui.frame();\n      this.setData({\n        frameTop: f.contentTop,\n        frameBottom: f.bottom,\n        frameStatus: f.statusBar,\n        frameNav: f.nav,\n        frameBar: f.top\n      });\n    }\n  }\n});\n","behaviors/toast.js":"module.exports = Behavior({\n  data: { toastShow: false, toastMsg: '' },\n  methods: {\n    showToast(msg) {\n      this.setData({ toastShow: true, toastMsg: msg });\n      clearTimeout(this._tt);\n      this._tt = setTimeout(() => this.setData({ toastShow: false }), 1600);\n    }\n  }\n});\n","components/x-btn/x-btn.js":"/* 按钮：type 映射现有样式类\n * primary 玫瑰主钮 / glass 玻璃钮 / cta 问卷大钮 / qa 玻璃药丸选项\n * block 撑满 / disabled 置灰禁点 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    type: { type: String, value: 'primary' },\n    block: { type: Boolean, value: false },\n    disabled: { type: Boolean, value: false }\n  },\n  methods: {\n    onTap(e) {\n      if (this.data.disabled) return;\n      this.triggerEvent('tap', e.detail);\n    }\n  }\n});\n","components/x-card/x-card.js":"/* 玻璃卡：rise 入场动画 0-6 级延迟 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    rise: { type: Number, value: 0 }   // 0=无动画 1-6=d1..d6\n  }\n});\n","components/x-icon/x-icon.js":"/* 图标：data-uri SVG 已带颜色，name 对应 icon.wxss 变体类 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    name: { type: String, value: '' },      // 例：ic3 / ic22-on / icspark\n    size: { type: Number, value: 32 }       // rpx\n  }\n});\n","components/x-msg/x-msg.js":"/* 聊天气泡：role ai/user；typing 显示三点输入态\n * tags 情绪标签；mem 引用档案标记；hideAv 连续同方隐藏头像 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    role: { type: String, value: 'ai' },\n    text: { type: String, value: '' },\n    tags: { type: Array, value: [] },\n    mem: { type: Boolean, value: false },\n    offline: { type: Boolean, value: false }, /* 离线剧本消息不标 AI 生成（票 63：诚实标识） */\n    hideAv: { type: Boolean, value: false },\n    typing: { type: Boolean, value: false },\n    animate: { type: Boolean, value: false }\n  }\n});\n","components/x-navbar/x-navbar.js":"/* 子页导航：标题 + 返回。顶部留白按设备实测（状态栏 + 胶囊导航带）。 */\nconst ui = require('../../utils/ui');\n\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    title: { type: String, value: '' },\n    dark: { type: Boolean, value: false },\n    back: { type: String, value: 'auto' },\n    backUrl: { type: String, value: '/pages/home/home' },\n    showBack: { type: Boolean, value: true }\n  },\n  data: { statusBar: 20, nav: 44, bar: 64 },\n  attached() {\n    const f = ui.frame();\n    this.setData({ statusBar: f.statusBar, nav: f.nav, bar: f.top });\n  },\n  methods: {\n    onBack() {\n      if (this.data.back === 'url') { wx.switchTab({ url: this.data.backUrl }); return; }\n      wx.navigateBack({ fail: () => wx.switchTab({ url: this.data.backUrl }) });\n    }\n  }\n});\n","components/x-sheet/x-sheet.js":"/* 底部弹层：mask + 圆角面板；show 控制，点 mask 触发 close 事件 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: { show: { type: Boolean, value: false } },\n  methods: {\n    onClose() { this.triggerEvent('close'); },\n    noop() {}\n  }\n});\n","custom-tab-bar/index.js":"const ui = require('../utils/ui');\n\nComponent({\n  options: { styleIsolation: 'apply-shared' },\n  data: {\n    bottom: 0,\n    selected: 0,\n    list: [\n      { path: 'pages/home/home', icon: '22', iconOn: '22-on', text: '首页' },\n      { path: 'pages/content/content', icon: '23', iconOn: '23-on', text: '成长' },\n      { path: 'pages/consultants/consultants', icon: '24', iconOn: '24-on', text: '陪伴' },\n      { path: 'pages/me/me', icon: '16', iconOn: '16-on', text: '我的' }\n    ]\n  },\n  attached() {\n    this.setData({ bottom: ui.frame().bottom + 12 });\n  },\n  methods: {\n    switchTab(e) {\n      const { path, index } = e.currentTarget.dataset;\n      wx.switchTab({ url: '/' + path });\n      this.setData({ selected: index });\n    }\n  }\n});\n","pages/cdetail/cdetail.js":"const toast = require('../../behaviors/toast');\nconst api = require('../../utils/api');\nconst frame = require('../../behaviors/frame');\nPage({\n  behaviors: [toast, frame],\n  data: { c: {} },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const id = require('../../stores/user').get('counselorId') || 'c1';\n    api.fetchCounselorDetail(id).then(c => this.setData({ c }));\n  }\n});\n","pages/chat/chat.js":"const toast = require('../../behaviors/toast');\nconst api = require('../../utils/api');\nconst frame = require('../../behaviors/frame');\n\nPage({\n  behaviors: [toast, frame],\n  data: {\n    msgs: [], typing: false, quickShow: false, inputVal: '',\n    cardsShow: true, cardsGone: false,\n    petFace: 'base', petPeek: false, petHappy: false, petWiggle: false,\n    crisisShow: false, calmOk: false, scrolled: false, scrollTo: '', kbH: 0, todayLabel: ''\n  },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    this._chatPlayed = false; this._chatBusy = false;\n    this._id = 0; this._timers = [];\n    const WD = ['日','一','二','三','四','五','六'];\n    const now = new Date();\n    const h = now.getHours();\n    this.setData({\n      cardsShow: true,\n      todayLabel: '星期' + WD[now.getDay()] + ' · ' + (h < 6 ? '深夜' : h < 12 ? '上午' : h < 18 ? '午后' : '晚上'),\n      dayM: now.getMonth() + 1,\n      dayD: now.getDate()\n    });\n    this._restore();\n    /* 开场白由对话域生成；有历史记录时直接续聊，不再重复寒暄 */\n    api.fetchChatScript().then(script => {\n      const name = require('../../stores/user').get('nickname') || '小美';\n      this._script = script.map(l => ({ ...l, text: l.text.replace(/\\{name\\}/g, name) }));\n      if (!this.data.msgs.length) this.startChat();\n    });\n  },\n  onShow() {\n    this._idleN = 0;\n    this._tf = setInterval(() => {\n      this._idleN++;\n      const f = this._idleN % 4 === 0 ? 'love' : 'blink';\n      this.petFace(f, f === 'love' ? 1500 : 1100);\n    });\n    /* 拨打热线会拉起拨号盘触发 onHide，把 5 秒解锁定时器清掉——回来必须补排，\n     * 否则危机卡永久不可关（二轮双轴 P2） */\n    if (this.data.crisisShow && !this.data.calmOk) {\n      this.later(() => this.setData({ calmOk: true }), 5000);\n    }\n  },\n  onHide() { this.clearTimers(); clearInterval(this._tf); },\n  onUnload() { this.clearTimers(); clearInterval(this._tf); },\n  clearTimers() { this._timers.forEach(clearTimeout); this._timers = []; this._chatBusy = false; this.setData({ typing: false }); },\n  later(fn, ms) { const id = setTimeout(fn, ms); this._timers.push(id); return id; },\n  scrollBottom() {\n    this.setData({ scrollTo: this.data.typing ? 'mT' : 'm' + (this._id - 1) });\n  },\n  addMsg(role, text, tags, mem, offline) {\n    const r = role === 'me' ? 'user' : role;\n    const msgs = this.data.msgs;\n    /* 同一方连续发言只显示一次头像 */\n    let hideAv = false;\n    if (r === 'ai' && msgs.length && msgs[msgs.length - 1].role === 'ai') hideAv = true;\n    const m = { id: this._id++, role: r, text, tags: tags || [], mem: !!mem, hideAv, offline: !!offline };\n    msgs.push(m);\n    this.setData({ msgs, typing: false });\n    this._persist();\n    this.scrollBottom();\n  },\n  _persist() {\n    try {\n      wx.setStorageSync('xixi_chat_msgs', this.data.msgs.slice(-60).map(m => ({ role: m.role, text: m.text })));\n    } catch (e) {}\n  },\n  _restore() {\n    let saved = [];\n    try { saved = wx.getStorageSync('xixi_chat_msgs') || []; } catch (e) {}\n    if (!Array.isArray(saved) || !saved.length) return;\n    const msgs = [];\n    let prev = '';\n    saved.forEach(s => {\n      const role = s.role === 'me' ? 'user' : s.role;\n      const hideAv = role === 'ai' && prev === 'ai';\n      msgs.push({ id: this._id++, role: role, text: s.text, tags: [], mem: false, hideAv: hideAv });\n      prev = role;\n    });\n    this._chatPlayed = true;\n    this.setData({ msgs: msgs });\n    api.seedChat(msgs);\n  },\n  clearChat() {\n    wx.showModal({\n      title: '清空对话',\n      content: '仅清除本机聊天记录，不影响其他数据。',\n      confirmText: '清空',\n      success: r => {\n        if (!r.confirm) return;\n        api.resetChat();\n        try { wx.removeStorageSync('xixi_chat_msgs'); } catch (e) {}\n        this._chatPlayed = false;\n        this.setData({ msgs: [], quickShow: false });\n        this.startChat();\n      }\n    });\n  },\n  startChat() {\n    if (this._chatPlayed) return;\n    if (!this._script) { this.later(() => this.startChat(), 300); return; }\n    this._chatPlayed = true; this._chatBusy = true;\n    this.setData({ quickShow: false });\n    const SCRIPT = this._script;\n    let i = 0;\n    const next = () => {\n      if (i >= SCRIPT.length) {\n        this._chatBusy = false;\n        this.setData({ quickShow: true });\n        this.scrollBottom();\n        return;\n      }\n      const item = SCRIPT[i];\n      if (item.role === 'ai') {\n        this.setData({ typing: true }); this.scrollBottom();\n        this.later(() => {\n          this.addMsg('ai', item.text, item.tags, item.mem, true); /* 本地剧本，非 LLM 生成 */\n          i++; this.later(next, 650);\n        }, 900 + Math.min(item.text.length * 8, 1400));\n      } else {\n        this.later(() => { this.addMsg('me', item.text); i++; this.later(next, 420); }, 380);\n      }\n    };\n    next();\n  },\n  quickBook() { this.quickSay('我想找陪伴师聊聊', true); },\n  quickTalk() { this.quickSay('再陪我聊聊吧', false); },\n  quickSay(text, target) {\n    if (this._chatBusy) return;\n    this._chatBusy = true;\n    this.dismissCards(); /* 欢迎卡浮层随首条消息退场，别压住 chips（四轮探针 F3） */\n    this.addMsg('me', text);\n    this.orbHappy();\n    if (target) {\n      /* 跳转前给一句 AI 过渡，不留「有问无答」的用户消息（红队 P2） */\n      this.setData({ typing: true }); this.scrollBottom();\n      this.later(() => {\n        this.setData({ typing: false });\n        this.addMsg('ai', '好，我先陪你做一个简短的梳理——几分钟就好，我好了解你现在的状态。');\n        this._chatBusy = false;\n        this.later(() => wx.navigateTo({ url: '/pages/prediag/prediag' }), 700);\n      }, 800);\n      return;\n    }\n    this.aiReply(text);\n  },\n  /* AI 回复统一走 API（mock 为本地回复池轮换） */\n  aiReply(text) {\n    this._chatBusy = true;\n    this.setData({ typing: true }); this.scrollBottom();\n    api.sendChatMessage(text).then(res => {\n      if (res.crisis) {\n        /* 回复里已经是危机话术：只弹卡，不再追加上一条本地危机文案 */\n        this.addMsg('ai', res.reply);\n        this.triggerCrisis(true);\n        return;\n      }\n      this.addMsg('ai', res.reply, res.offline ? ['离线示例'] : [], false, !!res.offline);\n      this._chatBusy = false;\n    });\n  },\n  onInput(e) { this.setData({ inputVal: e.detail.value }); },\n  onFocus() { this.setData({ petPeek: true }); },\n  onBlur() {\n    this.setData({ petPeek: false, kbH: 0 });\n    this.scrollBottom();\n  },\n  /* 真机键盘：不推页面，输入栏/小球手动贴键盘上沿 */\n  onKb(e) {\n    this.setData({ kbH: e.detail.height || 0 });\n    this.later(() => this.scrollBottom(), 120);\n  },\n  send() {\n    const v = (this.data.inputVal || '').trim();\n    if (!v || this._chatBusy) return;\n    /* 守卫通过即占位，堵住延迟置位前的双发窗口（红队 P1） */\n    this._chatBusy = true;\n    this.setData({ inputVal: '' });\n    const hadCards = !this._cardsGoneSent;\n    this.dismissCards();\n    this.orbHappy();\n    this.later(() => {\n      this.addMsg('me', v);\n      if (api.CRISIS_WORDS.some(w => v.includes(w))) { this.triggerCrisis(); return; }\n      this.aiReply(v);\n    }, hadCards ? 700 : 0);\n  },\n  dismissCards() {\n    if (this._cardsGoneSent) return;\n    this._cardsGoneSent = true;\n    this.setData({ cardsGone: true });\n    this.later(() => this.setData({ cardsShow: false }), 900);\n  },\n  triggerCrisis(replied) {\n    this._chatBusy = true;\n    if (!replied) { this.setData({ typing: true }); this.scrollBottom(); }\n    this.later(() => {\n      if (!replied) {\n        this.addMsg('ai', '我听到你此刻正在经历强烈的痛苦，这一定让你感到极度难受。当一个人经历这样的黑暗时刻，产生这些念头是创伤性的反应，这不是你的错。\\n\\n你现在并不孤单。我想让你知道，有很多人经历过类似的黑暗，并且走了出来。下面这些电话，可以立刻找到能帮到你的人。');\n      }\n      this.setData({ crisisShow: true, calmOk: false, typing: false });\n      this._chatBusy = false;\n      this.later(() => this.setData({ calmOk: true }), 5000);\n    }, replied ? 300 : 1200);\n  },\n  closeCrisis() {\n    if (!this.data.calmOk) return;\n    this.setData({ crisisShow: false });\n  },\n  callHotline() {\n    wx.makePhoneCall({ phoneNumber: '4001619995', fail: () => {} });\n  },\n  petFace(n, dur) {\n    this.setData({ petFace: n });\n    if (dur) { clearTimeout(this._pf); this._pf = setTimeout(() => this.setData({ petFace: 'base' }), dur); }\n  },\n  orbHappy() {\n    this.setData({ petHappy: true, petWiggle: false });\n    this.petFace('love', 1300);\n    this.later(() => this.setData({ petHappy: false }), 750);\n  },\n  pokePet() {\n    this.setData({ petHappy: false, petWiggle: true });\n    this.petFace('wow', 1200);\n    this.later(() => this.setData({ petWiggle: false }), 550);\n  },\n  goHome() { wx.switchTab({ url: '/pages/home/home' }); },\n  goPrediag() { wx.navigateTo({ url: '/pages/prediag/prediag' }); },\n  onScroll(e) {\n    const over = e.detail.scrollTop > 8;\n    if (over !== this.data.scrolled) this.setData({ scrolled: over });\n  }\n});\n","pages/consultants/consultants.js":"const api = require('../../utils/api');\nconst frame = require('../../behaviors/frame');\nPage({\n  behaviors: [frame],\n  data: { list: [], direction: '' },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const report = require('../../stores/user').get('report');\n    this.setData({ direction: (report && report.direction) || '' });\n    api.fetchCounselors().then(list => this.setData({ list }));\n  },\n  onShow() {\n    if (typeof this.getTabBar === 'function' && this.getTabBar()) this.getTabBar().setData({ selected: 2 });\n  },\n  goDetail(e) {\n    require('../../stores/user').set({ counselorId: e.currentTarget.dataset.id });\n    wx.navigateTo({ url: '/pages/cdetail/cdetail' });\n  }\n});\n","pages/content/content.js":"const toast = require('../../behaviors/toast');\nconst frame = require('../../behaviors/frame');\nconst api = require('../../utils/api');\nconst WD = ['日','一','二','三','四','五','六'];\nPage({\n  behaviors: [toast, frame],\n  data: {\n    weekRange: '', nbCount: 0,\n    jnlShow: false, jnlSent: false, jnlCrisis: false, jnlText: '', chipIdx: -1,\n    crisisShow: false, calmOk: false,\n    chips: ['平静','有点累','说不清','想被夸夸','一点开心'],\n    jnlDate: '', jnlDateFull: ''\n  },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const now = new Date();\n    const dow = (now.getDay() + 6) % 7;\n    const f = d => (d.getMonth() + 1) + '月' + d.getDate() + '日';\n    const mon = new Date(now); mon.setDate(now.getDate() - dow);\n    const sun = new Date(now); sun.setDate(now.getDate() - dow + 6);\n    this.setData({\n      weekRange: f(mon) + ' – ' + f(sun),\n      jnlDate: (now.getMonth() + 1) + '月' + now.getDate() + '日 周' + WD[now.getDay()],\n      jnlDateFull: (now.getMonth() + 1) + '月' + now.getDate() + '日 · 星期' + WD[now.getDay()]\n    });\n  },\n  onShow() {\n    if (typeof this.getTabBar === 'function' && this.getTabBar()) this.getTabBar().setData({ selected: 1 });\n    this.setData({ nbCount: this._journal().length });\n    /* 拨打热线触发 onHide 会清掉解锁定时器——回来补排，危机卡不能永久不可关（二轮双轴 P2） */\n    if (this.data.crisisShow && !this.data.calmOk) {\n      this.later(() => this.setData({ calmOk: true }), 5000);\n    }\n  },\n  onHide() { this.clearTimers(); },\n  onUnload() { this.clearTimers(); },\n  clearTimers() { (this._timers || []).forEach(clearTimeout); this._timers = []; },\n  later(fn, ms) { this._timers = this._timers || []; const id = setTimeout(fn, ms); this._timers.push(id); return id; },\n  _journal() {\n    try {\n      const list = wx.getStorageSync('xixi_journal');\n      return Array.isArray(list) ? list : [];\n    } catch (e) {\n      return [];\n    }\n  },\n  openJnl() { this.setData({ jnlShow: true, jnlSent: false, jnlCrisis: false }); },\n  closeJnl() { this.setData({ jnlShow: false }); },\n  pickChip(e) { this.setData({ chipIdx: +e.currentTarget.dataset.i }); },\n  onJnlText(e) { this.setData({ jnlText: e.detail.value }); },\n  sendJnl() {\n    if (this._jnlBusy) return; /* 防连点双写（红队 P2）；异步收尾复位，守卫跨事件有效 */\n    const text = this.data.jnlText.trim();\n    if (!text) { this.showToast('先写一句吧，哪怕一句也好'); return; }\n    this._jnlBusy = true;\n    this.later(() => { this._jnlBusy = false; }, 600);\n    const crisis = api.CRISIS_WORDS.some(w => text.includes(w));\n    const list = this._journal();\n    list.push({ ts: Date.now(), date: this.data.jnlDate, text: text, chip: this.data.chips[this.data.chipIdx] || '' });\n    try { wx.setStorageSync('xixi_journal', list.slice(-200)); } catch (e) {}\n    this.setData({ jnlSent: true, jnlCrisis: crisis, nbCount: list.length, jnlText: '' });\n    if (crisis) {\n      this.setData({ crisisShow: true, calmOk: false });\n      this.later(() => this.setData({ calmOk: true }), 5000);\n      return;\n    }\n    this.showToast('已放进你的手记');\n  },\n  closeCrisis() {\n    if (!this.data.calmOk) return;\n    this.setData({ crisisShow: false });\n  },\n  callHotline() {\n    wx.makePhoneCall({ phoneNumber: '4001619995', fail: () => {} });\n  }\n});\n","pages/home/home.js":"const mood = require('../../utils/mood');\nconst api = require('../../utils/api');\nconst toast = require('../../behaviors/toast');\nconst frame = require('../../behaviors/frame');\nconst POKES = ['西米蹭了蹭你 ◡̈','西米绕着你转了一圈','被你戳得晃了晃','西米眨了眨眼','再戳我就要飘走啦','西米听见了你的召唤','我在，一直都在'];\nPage({\n  behaviors: [toast, frame],\n  data: {\n    bubTxt: '', xFace: 'base', careOn: false, careTip: '', announcement: '', announceClosed: false,\n    qTxt: '', qAu: '', qImg: '', qTxtShare: '',\n    gcDay: '', gcYM: '', todayMood: '', todayFace: '', streak: 0,\n    shareShow: false, entering: false\n  },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const h = new Date().getHours();\n    const greet = h < 5 ? '夜深了' : h < 11 ? '早上好' : h < 14 ? '中午好' : h < 18 ? '下午好' : '晚上好';\n    this._bubs = [greet + '呀，{n}～','今天也辛苦啦','想我了就戳戳我','心里有事？说给我听','喝口水，慢慢来','我在呢，不急','今天照顾好自己了吗','风吹过来的时候，我也在'];\n    this._bi = 0;\n    this.renderBub();\n    /* 金句：mock 按日期轮换，真实前端走 GET /api/daily-quote */\n    api.fetchDailyQuote().then(q => {\n      this.setData({ qTxt: '「' + q.text + '」', qAu: q.author, qImg: q.image, qTxtShare: '「' + q.text + '」' });\n    });\n    /* 心情日历 */\n    this._cal = mood.calendar();\n    this.renderGc();\n  },\n  onShow() {\n    if (typeof this.getTabBar === 'function' && this.getTabBar()) this.getTabBar().setData({ selected: 0 });\n    const app = getApp();\n    this.setData({ careOn: require('../../stores/user').get('careOn') });\n    /* 关怀提醒文案：admin remote.careTip 实时下发（票 61），未配置走包内兜底 */\n    const content = require('../../utils/domains/content');\n    content.careTip().then(t => { if (t) this.setData({ careTip: t }); }).catch(() => {});\n    /* 运营公告（票 65）：remote.announcement 非空才展示，会话内可关闭 */\n    content.announcement().then(a => { if (a) this.setData({ announcement: a }); }).catch(() => {});\n    if (app.globalData.justEntered) {\n      app.globalData.justEntered = false;\n      this.setData({ entering: true });\n      this._te = setTimeout(() => this.setData({ entering: false }), 800);\n    }\n    this._tb = setInterval(() => { this._bi = (this._bi + 1) % this._bubs.length; this.renderBub(); }, 5000);\n    this._idleN = 0;\n    this._tf = setInterval(() => {\n      this._idleN++;\n      const f = this._idleN % 4 === 0 ? 'love' : 'blink';\n      this.xFace(f, f === 'love' ? 1500 : 1100);\n    }, 4000);\n    this._cal = mood.calendar();\n    this.renderGc();\n  },\n  onUnload() { clearInterval(this._tb); clearInterval(this._tf); clearTimeout(this._te); },\n  onHide() { clearInterval(this._tb); clearInterval(this._tf); },\n  renderBub() { this.setData({ bubTxt: this._bubs[this._bi].replace('{n}', require('../../stores/user').get('nickname') || '小美') }); },\n  renderGc() {\n    const cal = this._cal;\n    const mi = cal.hist[cal.today], n = mi != null ? mood.NAMES[mi] : null;\n    this.setData({\n      gcDay: cal.today, gcYM: cal.ym,\n      todayMood: n || '', todayFace: mood.faceUri(n || mood.NAMES[0]),\n      streak: mood.streak()\n    });\n  },\n  xFace(n, dur) {\n    this.setData({ xFace: n });\n    if (dur) { clearTimeout(this._xf); this._xf = setTimeout(() => this.setData({ xFace: 'base' }), dur); }\n  },\n  pokeXixi() {\n    this.xFace('wow', 1300);\n    this.showToast(POKES[Math.floor(Math.random() * POKES.length)]);\n  },\n  goChat() { wx.navigateTo({ url: '/pages/chat/chat' }); },\n  closeAnnounce() { this.setData({ announceClosed: true }); },\n  goMoodcal() { wx.navigateTo({ url: '/pages/moodcal/moodcal' }); },\n  goSleep() { wx.navigateTo({ url: '/pages/sleep/sleep' }); },\n  openShare() { this.setData({ shareShow: true }); },\n  /* 转发：默认带金句文案 */\n  onShareAppMessage() {\n    return {\n      title: this.data.qTxt + ' —— 西米 · AI情感陪伴',\n      path: '/pages/home/home',\n      imageUrl: this.data.qImg\n    };\n  },\n  closeShare() { this.setData({ shareShow: false }); },\n  noop() {}\n});\n","pages/launch/launch.js":"const frame = require('../../behaviors/frame');\nPage({\n  behaviors: [frame],\n  data: { exiting: false },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    /* 已答过问卷的老用户直接进首页；新用户走引导 */\n    const user = require('../../stores/user');\n    const answers = user.get('obAnswers') || {};\n    const seen = !!user.get('onboarded') || Object.keys(answers).length > 0;\n    this._t1 = setTimeout(() => this.setData({ exiting: true }), 1350);\n    this._t2 = setTimeout(() => {\n      if (seen) wx.switchTab({ url: '/pages/home/home' });\n      else wx.redirectTo({ url: '/pages/onboard/onboard' });\n    }, 1600);\n  },\n  onUnload() { clearTimeout(this._t1); clearTimeout(this._t2); }\n});\n","pages/me/me.js":"const toast = require('../../behaviors/toast');\nconst frame = require('../../behaviors/frame');\nPage({\n  behaviors: [toast, frame],\n  data: { careOn: false, nickname: '小美' },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const user = require('../../stores/user');\n    this.setData({ careOn: user.get('careOn') });\n  },\n  onShow() {\n    if (typeof this.getTabBar === 'function' && this.getTabBar()) this.getTabBar().setData({ selected: 3 });\n    /* 昵称随档案改动即时刷新（红队 P2） */\n    const user = require('../../stores/user');\n    this.setData({ nickname: user.get('nickname') || '小美' });\n  },\n  toggleCare() {\n    const on = !this.data.careOn;\n    require('../../stores/user').set({ careOn: on });\n    wx.setStorageSync('xixi_care', on);\n    this.setData({ careOn: on });\n    this.showToast(on ? '已开启生理期关怀 · 首页将显示经期提醒' : '已关闭 · 首页不再显示经期信息');\n  },\n  goProfile() { wx.navigateTo({ url: '/pages/profile/profile' }); },\n  goPrivacy() { wx.navigateTo({ url: '/pages/privacy/privacy' }); }\n});\n","pages/moodcal/moodcal.js":"const mood = require('../../utils/mood');\nconst api = require('../../utils/api');\nconst toast = require('../../behaviors/toast');\nconst frame = require('../../behaviors/frame');\nconst MOOD_REPLY = { '平静':'平静很好 · 今天也稳稳的','委屈':'委屈就说出来 · 西米听着','焦虑':'先深呼吸一下 · 我在','烦躁':'烦躁倒给我 · 就不硌你了','难过':'抱抱你 · 难过不用藏' };\nPage({\n  behaviors: [toast, frame],\n  data: {},\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const cal = mood.calendar();\n    this._cal = cal;\n    this.setData({\n      monthTitle: cal.monthTitle, weekCap: cal.weekCap,\n      cells: cal.cells, week: cal.week,\n      colors: mood.GCM, colorsArr: Object.keys(mood.GCM).map(k => mood.GCM[k]),\n      faces: mood.NAMES.map(n => mood.faceUri(n)),\n      moods: mood.NAMES,\n      selMood: cal.hist[cal.today],\n      streak: mood.streak()\n    });\n  },\n  pickMood(e) {\n    const i = +e.currentTarget.dataset.m;\n    api.saveMood(i);\n    const cal = mood.calendar();\n    this._cal = cal;\n    this.setData({ selMood: i, streak: mood.streak(), cells: cal.cells, week: cal.week });\n    this.showToast(MOOD_REPLY[mood.NAMES[i]] || '打卡成功');\n  },\n  goBack() { wx.navigateBack({ fail: () => wx.switchTab({ url: '/pages/home/home' }) }); }\n});\n","pages/onboard/onboard.js":"const api = require('../../utils/api');\nconst frame = require('../../behaviors/frame');\nconst OB_FX = ['wipe', 'blinds', 'zoom', 'peel'];\nlet OB_STEPS = [];\n\nPage({\n  behaviors: [frame],\n  data: {\n    cur: 0, step: { type: 'multi', title: '', sub: '', opts: [], max: 3 }, stepNo: '01', skipTxt: '',\n    metaLab: 'CHECKED', maxLab: ' / 3', cnt: 0,\n    ctaHide: false, ctaDis: true, ctaTxt: '继 续', ctaShake: false,\n    selArr: [], name: '', chipOn: false, shakeIdx: -1,\n    titleChars: [], typedTitle: '', note: '',\n    envOpen: false, envSealed: false, envFlutter: false, envCenter: false, envFly: false, wrapOut: false,\n    safeOn: false, hearts: [], fxWipe: false, fxBlinds: false, pageIn: '', pageKey: 0, busy: false,\n    loadErr: false\n  },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    this._answers = {};\n    this._sel = [];\n    this._twToken = 0;\n    this._timers = [];\n    this._load();\n  },\n  _load() {\n    this.setData({ loadErr: false });\n    api.fetchOnboardQuestions().then(steps => {\n      OB_STEPS = steps;\n      this.loadStep(0, '');\n    }).catch(err => {\n      /* 题目加载失败必须有可重试的错误分支，不能停在空白步骤（红队 P2） */\n      console.error('onboard load failed', err && err.message);\n      this.setData({ loadErr: true });\n    });\n  },\n  retryLoad() { this._load(); },\n  onUnload() { this._timers.forEach(clearTimeout); clearInterval(this._tw); },\n  later(fn, ms) { const id = setTimeout(fn, ms); this._timers.push(id); return id; },\n\n  loadStep(idx, pageIn) {\n    const st = OB_STEPS[idx];\n    /* 恢复此前选择（返回时） */\n    const prev = this._answers[idx] || [];\n    const selArr = st.opts ? st.opts.map(o => prev.includes(o)) : [];\n    this._sel = st.opts ? selArr.map((v, i) => (v ? i : -1)).filter(i => i >= 0) : [];\n    this._twToken++;\n    clearInterval(this._tw);\n    let titleChars = [];\n    if (idx === 0) {\n      titleChars = [...st.title].map((c, k) => ({ c, d: k * 32 }));\n    }\n    this.setData({\n      cur: idx, step: st, stepNo: '0' + (idx + 1), skipTxt: st.skip,\n      metaLab: st.type === 'multi' ? 'CHECKED' : st.type === 'single' ? 'SINGLE CHOICE' : 'OPTIONAL',\n      maxLab: st.type === 'multi' ? ' / ' + st.max : '',\n      ctaHide: st.type === 'single', ctaTxt: st.type === 'name' ? '开 启 陪 伴' : '继 续',\n      cnt: this._sel.length, selArr, name: '', chipOn: false, shakeIdx: -1,\n      titleChars, typedTitle: '', note: st.note, pageIn: pageIn || '', pageKey: this.data.pageKey + 1\n    });\n    if (idx === 3) this.typewrite(st.title);\n    this.later(() => this.setData({ pageIn: '' }), 700);\n  },\n  typewrite(text) {\n    const token = ++this._twToken;\n    let i = 0;\n    this.setData({ typedTitle: '' });\n    this._tw = setInterval(() => {\n      if (token !== this._twToken) { clearInterval(this._tw); return; }\n      if (i < text.length) { i++; this.setData({ typedTitle: text.slice(0, i) }); }\n      else clearInterval(this._tw);\n    }, 85);\n  },\n\n  envOpen() { this.setData({ envOpen: true, envSealed: false }); },\n  envFlutter() {\n    this.setData({ envFlutter: true });\n    this.later(() => this.setData({ envFlutter: false }), 600);\n  },\n  envSeal() {\n    this.setData({ envOpen: false, envSealed: true });\n    this.later(() => this.setData({ envSealed: false }), 520);\n  },\n\n  pickOpt(e) {\n    const k = +e.currentTarget.dataset.k;\n    const st = OB_STEPS[this.data.cur];\n    if (st.type === 'single') {\n      if (this.data.busy) return;\n      const selArr = st.opts.map((_, i) => i === k);\n      this._sel = [k];\n      this._answers[this.data.cur] = [st.opts[k]];\n      this.setData({ selArr, cnt: 1 });\n      this.envFlutter();\n      if (st.opts[k] === '感到绝望') {\n        this.setData({ busy: true });\n        this.later(() => { this.setData({ busy: false, safeOn: true }); }, 520);\n        return;\n      }\n      this.setData({ busy: true });\n      this.later(() => { this.setData({ busy: false }); this.goNext(); }, 620);\n      return;\n    }\n    /* multi */\n    const selArr = this.data.selArr.slice();\n    if (selArr[k]) {\n      selArr[k] = false;\n      this._sel = this._sel.filter(i => i !== k);\n    } else {\n      if (this._sel.length >= st.max) {\n        this.setData({ shakeIdx: k });\n        this.later(() => this.setData({ shakeIdx: -1 }), 600);\n        return;\n      }\n      selArr[k] = true;\n      this._sel.push(k);\n      this.envOpen();\n    }\n    this._answers[this.data.cur] = this._sel.map(i => st.opts[i]);\n    this.setData({ selArr, cnt: this._sel.length, ctaDis: this._sel.length === 0 });\n  },\n\n  onName(e) {\n    const v = e.detail.value.trim();\n    this.setData({ name: v, chipOn: false, ctaDis: !v });\n  },\n  commitName() {\n    if (!this.data.name.trim()) return;\n    this.setData({ name: this.data.name.trim() });\n  },\n  quickName() {\n    const on = !this.data.chipOn;\n    this.setData({ chipOn: on, name: on ? '小美' : '', ctaDis: !on });\n    if (on) this.envOpen();\n  },\n\n  ctaTap() {\n    if (this.data.busy) return;\n    const st = OB_STEPS[this.data.cur];\n    if (st.type === 'multi' && this._sel.length === 0) { this.shakeCta(); return; }\n    if (st.type === 'name') {\n      if (!this.data.name.trim()) { this.shakeCta(); return; }\n      this._answers[4] = [this.data.name.trim()];\n      this.goNext();\n      return;\n    }\n    if (st.type === 'multi') {\n      this.envSeal();\n      this.later(() => this.goNext(), 120);\n    }\n  },\n  shakeCta() {\n    this.setData({ ctaShake: true });\n    this.later(() => this.setData({ ctaShake: false }), 600);\n  },\n  skip() {\n    if (this.data.busy) return;\n    this.envFlutter();\n    this.goNext();\n  },\n  goBack() {\n    if (this.data.busy || this.data.cur === 0) return;\n    this.loadStep(this.data.cur - 1, 'zoomIn');\n  },\n\n  goNext() {\n    if (this.data.busy) return;\n    if (this.data.cur >= OB_STEPS.length - 1) { this.finishOb(); return; }\n    this.setData({ busy: true, envOpen: false });\n    const fx = OB_FX[this.data.cur];\n    const next = this.data.cur + 1;\n    if (fx === 'wipe') {\n      this.setData({ fxWipe: true });\n      this.later(() => this.loadStep(next, ''), 430);\n      this.later(() => this.setData({ fxWipe: false, busy: false }), 950);\n    } else if (fx === 'blinds') {\n      this.setData({ fxBlinds: true });\n      this.later(() => this.loadStep(next, ''), 750);\n      this.later(() => this.setData({ fxBlinds: false, busy: false }), 1400);\n    } else {\n      this.loadStep(next, 'zoomIn');\n      this.later(() => this.setData({ busy: false }), 700);\n    }\n  },\n\n  finishOb() {\n    if (this.data.busy) return;\n    this.setData({ busy: true, note: '收到啦。', envOpen: true });\n    const userStore = require('../../stores/user');\n    userStore.set({ obAnswers: this._answers, onboarded: true });\n    if (this._answers[4] && this._answers[4][0]) userStore.set({ nickname: this._answers[4][0] });\n    /* 提交答卷：云端按 openid 落库，失败不阻断 */\n    api.submitOnboard(this._answers).then(res => {\n      if (res.nickname) userStore.set({ nickname: res.nickname });\n    });\n    this.later(() => this.setData({ wrapOut: true }), 300);\n    this.later(() => this.setData({ envCenter: true }), 600);\n    this.later(() => {\n      this.setData({\n        hearts: [\n          { dx: -88, rr: -26, delay: 0 },\n          { dx: 0, rr: 0, delay: 0.18 },\n          { dx: 88, rr: 26, delay: 0.36 }\n        ]\n      });\n    }, 1550);\n    this.later(() => this.setData({ envFly: true }), 2550);\n    this.later(() => wx.redirectTo({ url: '/pages/summary/summary' }), 3370);\n  },\n\n  safeOk() {\n    this.setData({ safeOn: false });\n    this.later(() => this.goNext(), 260);\n  },\n  callHotline() {\n    wx.makePhoneCall({ phoneNumber: '4001619995', fail: () => {} });\n  }\n});\n","pages/prediag/prediag.js":"const api = require('../../utils/api');\nconst frame = require('../../behaviors/frame');\nPage({\n  behaviors: [frame],\n  data: { msgs: [], typing: true, opts: [], progress: [true, false, false, false, false], gen: false, loadErr: false, submitErr: false },\n  onLoad() { this.syncFrame(); this._step = 0; this._id = 0; this._running = true; this._timers = []; this._answers = [];\n    this._load();\n  },\n  _load() {\n    this.setData({ loadErr: false, typing: true });\n    api.fetchPrediagQuestions().then(qs => {\n      this._qs = qs;\n      this.later(() => {\n        this.addMsg('ai', qs[0].q);\n        this.setData({ opts: qs[0].opts, typing: false });\n        this._running = false;\n      }, 700);\n    }).catch(err => {\n      /* 题目加载失败要有错误分支，不能让 typing 永转（红队 P2） */\n      console.error('prediag load failed', err && err.message);\n      this.setData({ loadErr: true, typing: false });\n    });\n  },\n  retryLoad() { this._load(); },\n  onUnload() { this._timers.forEach(clearTimeout); },\n  later(fn, ms) { const id = setTimeout(fn, ms); this._timers.push(id); return id; },\n  addMsg(role, text) {\n    const msgs = this.data.msgs;\n    let hideAv = false;\n    if (role === 'ai' && msgs.length && msgs[msgs.length - 1].role === 'ai') hideAv = true;\n    msgs.push({ id: this._id++, role, text, hideAv });\n    this.setData({ msgs });\n    wx.pageScrollTo({ scrollTop: 99999, duration: 300 });\n  },\n  answer(e) {\n    if (this._running) return;\n    this._running = true;\n    const text = e.currentTarget.dataset.t;\n    this.addMsg('me', text);\n    this._answers.push(text);\n    this._step++;\n    const prog = this.data.progress.map((_, i) => i < this._step);\n    this.setData({ opts: [], progress: prog });\n    if (this._step >= this._qs.length) {\n      this.later(() => this._submit(), 400);\n      return;\n    }\n    this.setData({ typing: true });\n    this.later(() => {\n      this.addMsg('ai', this._qs[this._step].q);\n      this.setData({ opts: this._qs[this._step].opts, typing: false });\n      this._running = false;\n    }, 850);\n  },\n  _submit() {\n    this.setData({ gen: true, submitErr: false });\n    wx.pageScrollTo({ scrollTop: 99999, duration: 300 });\n    /* 提交答卷 → 报告存 globalData 供 report 页读取；失败给可重试分支 */\n    api.submitPrediagAnswers(this._answers).then(res => {\n      require('../../stores/user').set({ report: res.report });\n      this.later(() => wx.redirectTo({ url: '/pages/report/report' }), 1200);\n    }).catch(err => {\n      console.error('prediag submit failed', err && err.message);\n      this.setData({ gen: false, submitErr: true, _running: false });\n    });\n  },\n  retrySubmit() { this._submit(); },\n  goBack() { wx.navigateBack({ fail: () => wx.navigateTo({ url: '/pages/chat/chat' }) }); }\n});\n","pages/privacy/privacy.js":"const frame = require('../../behaviors/frame');\nPage({ behaviors: [frame], data: {}, onLoad() { this.syncFrame(); } });\n","pages/profile/profile.js":"const toast = require('../../behaviors/toast');\nconst frame = require('../../behaviors/frame');\nconst api = require('../../utils/api');\nconst moodDomain = require('../../utils/domains/mood');\n\nconst LABELS = ['当前困扰', '陪伴偏好', '关系阶段', '当前情绪', '称呼'];\n\nfunction list(key) {\n  try {\n    const v = wx.getStorageSync(key);\n    return Array.isArray(v) ? v : [];\n  } catch (e) {\n    return [];\n  }\n}\n\nPage({\n  behaviors: [toast, frame],\n  data: { nickname: '', answers: [], moodCount: 0, journalCount: 0, removing: false },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const user = require('../../stores/user');\n    const raw = user.get('obAnswers') || {};\n    const answers = [];\n    Object.keys(raw).sort().forEach(k => {\n      const v = raw[k];\n      const text = Array.isArray(v) ? v.join('、') : String(v || '');\n      if (text) answers.push({ label: LABELS[Number(k)] || ('问题 ' + k), value: text });\n    });\n    this.setData({\n      nickname: user.get('nickname') || '',\n      answers: answers,\n      moodCount: moodDomain.read().length,\n      journalCount: list('xixi_journal').length\n    });\n  },\n  onName(e) { this.setData({ nickname: e.detail.value.trim() }); },\n  saveName() {\n    const name = this.data.nickname;\n    if (!name) return;\n    require('../../stores/user').set({ nickname: name });\n    api.submitOnboard(Object.assign({}, require('../../stores/user').get('obAnswers'), { 4: [name] }))\n      .then(res => this.showToast(res && res.offline ? '已保存在本机，联网后同步' : '已保存'));\n  },\n  removeAll() {\n    wx.showModal({\n      title: '删除全部数据',\n      content: '问卷、称呼、心情记录、手记都会被删除，云端备份同步清除。',\n      confirmText: '删除',\n      confirmColor: '#A96678',\n      success: r => { if (r.confirm) this._doRemove(); }\n    });\n  },\n  _doRemove() {\n    api.resetChat();\n    ['xixi_moods', 'xixi_journal', 'xixi_chat_msgs', 'xixi_user_state', 'xixi_care', 'xixi_server_ts', 'xixi_trace', 'xixi_trace_home'].forEach(k => {\n      try { wx.removeStorageSync(k); } catch (e) {}\n    });\n    /* 旧版按天存的心情键一并清掉，否则删除当天记录会「复活」 */\n    try {\n      const info = wx.getStorageInfoSync ? wx.getStorageInfoSync() : { keys: [] };\n      (info.keys || []).forEach(k => { if (k.indexOf('xixi_mood_') === 0) wx.removeStorageSync(k); });\n    } catch (e) {}\n    const user = require('../../stores/user');\n    /* onboarded 必须归位：删除后重进要走问卷（GO-LIVE 走查第 8 步口径，四轮探针 F1） */\n    user.set({ nickname: '小美', obAnswers: null, careOn: false, report: null, onboarded: false });\n    this.setData({ removing: true });\n    api.deleteProfile().then(res => {\n      if (res && res.ok) {\n        this.showToast('已删除');\n        wx.reLaunch({ url: '/pages/launch/launch' });\n        return;\n      }\n      this.setData({ removing: false });\n      wx.showModal({\n        title: '删除没有完成',\n        content: '云端暂时没有确认删除，请检查网络后重试。本机记录已清除。',\n        showCancel: false\n      });\n    });\n  }\n});\n","pages/report/report.js":"const frame = require('../../behaviors/frame');\nPage({\n  behaviors: [frame],\n  data: { report: null, failed: false },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    /* 报告来自初步梳理提交（stores/user）。没有真实结果时不展示任何演示内容 */\n    const r = require('../../stores/user').get('report');\n    if (r && r.conflict) this.setData({ report: r });\n    else this.setData({ failed: true });\n  },\n  goConsultants() { wx.switchTab({ url: '/pages/consultants/consultants' }); },\n  retry() { wx.redirectTo({ url: '/pages/prediag/prediag' }); },\n  goHome() { wx.switchTab({ url: '/pages/home/home' }); }\n});\n","pages/sleep/sleep.js":"const toast = require('../../behaviors/toast');\nconst frame = require('../../behaviors/frame');\nPage({\n  behaviors: [toast, frame],\n  onLoad() { this.syncFrame(); }, /* 骨架度量（票 30） */\n  data: { playingIdx: -1 },\n  play(e) {\n    this.setData({ playingIdx: +e.currentTarget.dataset.i });\n    this.showToast('音频内容即将开放');\n  }\n});\n","pages/summary/summary.js":"const frame = require('../../behaviors/frame');\nconst TROUBLE_SHORT = { '伴侣沟通不顺':'伴侣沟通','婚姻出现变化':'婚姻变化','对关系感到不安':'关系中的不安','家庭/亲子压力':'家庭和亲子压力','情绪起伏大':'情绪压力','工作生活压力大':'工作生活压力','失眠、想太多':'睡眠困扰','孤独、没人理解':'孤独感','想更了解自己':'自我探索','只是想说说话':'倾诉的需要' };\nconst MOOD_PHRASE = { '比较平静':'此刻比较平静','有些委屈':'现在有些委屈','焦虑不安':'现在有些焦虑不安','生气烦躁':'现在有点烦躁','疲惫无力':'现在很疲惫','难过想哭':'现在心里难过','感到绝望':'现在正经历很难的时刻','说不清楚':'感受还有些说不清楚' };\nconst PREF_PHRASE = { '先听我说完':'先听你说完','帮我把事理清楚':'帮你把事理清楚','帮我看见真实感受':'陪你看见真实感受','一起想想怎么办':'陪你一起想办法','提醒我注意安全与边界':'提醒你注意安全与边界','需要时联系真人陪伴师':'需要时帮你联系真人陪伴师','还不确定，先聊聊':'先轻松聊聊' };\nconst PREF_SHORT = { '帮我把事理清楚':'帮你理清' };\nPage({\n  behaviors: [frame],\n  data: { title: '', desc: '' },\n  onLoad() {\n    this.syncFrame(); /* 骨架度量：behavior 生命周期在页面里不执行，必须显式调用（票 30） */\n    const user = require('../../stores/user'), a = user.get('obAnswers') || {};\n    const troubles = a[0] || [], prefer = a[1] || [], mood = (a[3] || [])[0] || '';\n    const name = (a[4] || [])[0] || '你';\n    if ((a[4] || [])[0]) require('../../stores/user').set({ nickname: (a[4] || [])[0] });\n    const t = troubles.map(x => TROUBLE_SHORT[x] || x);\n    const tTxt = t.length ? ('最近你主要在经历' + t.slice(0, 2).join('和') + (t.length > 2 ? '等方面的困扰' : '')) : '最近你想找个人说说话';\n    const mTxt = mood ? ('，' + (MOOD_PHRASE[mood] || '现在有些' + mood)) : '';\n    let pTxt = '；我会先按你的节奏陪你，不急着下结论';\n    if (prefer.length) {\n      pTxt = '；你希望' + (PREF_PHRASE[prefer[0]] || prefer[0]) +\n        (prefer[1] ? ('，再' + (PREF_SHORT[prefer[1]] || PREF_PHRASE[prefer[1]] || prefer[1])) : '');\n    }\n    this.setData({\n      title: name + '，我大致了解了',\n      desc: tTxt + mTxt + pTxt + '。我们不用一次解决所有事，从你现在最想说的开始就好。'\n    });\n  },\n  toChat() { wx.navigateTo({ url: '/pages/chat/chat' }); },\n  toHome() { wx.switchTab({ url: '/pages/home/home' }); }\n});\n","services/auth.js":"/* ============================================================\n * 登录态服务\n * - 云函数模式（USE_CLOUD）：身份由云函数上下文 openid 提供，前端不留 token\n * - USE_MOCK：本地模拟\n * - 其余：wx.login → code2Session（HTTP 网关，已弃用）\n * ============================================================ */\nconst user = require('../stores/user');\n\nconst TTL = 6 * 24 * 3600 * 1000; // token 有效期 6 天\n\nfunction _mockLogin() {\n  return Promise.resolve({ token: 'mock-token-' + Date.now(), userId: 'mock-user' });\n}\n\nfunction code2Session() {\n  return new Promise((resolve, reject) => {\n    /* 函数内 require：避免 auth ↔ api 循环依赖（api 顶层不引 auth） */\n    const api = require('../utils/api');\n    if (api.USE_CLOUD) {\n      resolve({ token: 'cloud', userId: '' });\n      return;\n    }\n    wx.login({\n      success(res) {\n        if (!res.code) { reject(new Error('wx.login 无 code')); return; }\n        if (api.USE_MOCK) { resolve(_mockLogin()); return; }\n        api.rawRequest('/api/auth/login', 'POST', { code: res.code })\n          .then(resolve).catch(reject);\n      },\n      fail: reject\n    });\n  });\n}\n\nfunction ensureSession(force) {\n  const { token, tokenAt } = user.get();\n  if (!force && token && tokenAt && Date.now() - tokenAt < TTL) {\n    return Promise.resolve(token);\n  }\n  return code2Session().then(res => {\n    user.set({ token: res.token, userId: res.userId, tokenAt: Date.now() });\n    return res.token;\n  });\n}\n\n/* 带 token 的请求；401 强制重登一次后重试 */\nfunction authedRequest(path, method, data) {\n  return ensureSession().then(() => {\n    const api = require('../utils/api');\n    return api.rawRequest(path, method, data, user.get('token'));\n  }).catch(err => {\n    if (err && /401|token/i.test(err.message || '')) {\n      return ensureSession(true).then(() => {\n        const api = require('../utils/api');\n        return api.rawRequest(path, method, data, user.get('token'));\n      });\n    }\n    throw err;\n  });\n}\n\nmodule.exports = { ensureSession, authedRequest };\n","stores/user.js":"/* ============================================================\n * 用户状态 store —— 全局状态唯一入口\n * 之前散在 app.globalData 的字段全部收拢到这里：\n *   nickname / obAnswers / careOn / report / counselorId\n * 内存态 + storage 持久化同步；页面不再直接碰 globalData\n * ============================================================ */\nconst KEY = 'xixi_user_state';\n\nconst state = {\n  nickname: '小美',\n  obAnswers: null,     // 问卷答卷 {0:[..],...}\n  careOn: false,       // 生理期关怀授权\n  onboarded: false,    // 是否走完过引导（跳过全部步骤也算）\n  report: null,        // 预梳理报告\n  counselorId: '',     // 当前查看的陪伴师\n  token: '',           // 登录态（services/auth 维护）\n  userId: ''\n};\n\n/* 启动时从 storage 恢复可持久化字段 */\nfunction restore() {\n  try {\n    const saved = wx.getStorageSync(KEY);\n    if (saved) {\n      ['nickname', 'careOn', 'token', 'userId', 'obAnswers', 'onboarded'].forEach(k => {\n        if (saved[k] !== undefined && saved[k] !== '') state[k] = saved[k];\n      });\n    }\n  } catch (e) {}\n}\nrestore();\n\n/* 持久化白名单（report 等会话态不落盘） */\nconst PERSIST = ['nickname', 'careOn', 'token', 'userId', 'obAnswers', 'onboarded'];\n\nfunction set(patch) {\n  Object.assign(state, patch);\n  const saved = {};\n  PERSIST.forEach(k => { saved[k] = state[k]; });\n  try { wx.setStorageSync(KEY, saved); } catch (e) {}\n  return state;\n}\n\nfunction get(key) {\n  return key ? state[key] : state;\n}\n\nmodule.exports = { get, set, state };\n","tools/__tests__/api-cloud.test.js":"/* 接缝测试：api.js 只经 wx.cloud.callFunction 取数，且失败时降级不抛错 */\nconst path = require('path');\n\nfunction loadApi(impl) {\n  jest.resetModules();\n  const calls = [];\n  global.wx = {\n    cloud: {\n      callFunction(opts) {\n        calls.push(opts);\n        impl(opts);\n      }\n    },\n    getStorageSync: () => '',\n    setStorageSync: () => {},\n    removeStorageSync: () => {}\n  };\n  return { api: require(path.join(__dirname, '../../utils/api.js')), calls };\n}\n\nconst ok = (result) => (opts) => opts.success({ result });\nconst fail = () => (opts) => opts.fail({ errMsg: 'network down' });\n\ntest('问卷答完：写 xixiData 的 profile 域', async () => {\n  const { api, calls } = loadApi(ok({ ok: true, openid: 'o1' }));\n  const res = await api.submitOnboard({ 0: ['伴侣沟通不顺'], 4: '小南' });\n  expect(calls[0].name).toBe('xixiData');\n  expect(calls[0].data.action).toBe('push');\n  expect(calls[0].data.payload.profile.nickname).toBe('小南');\n  expect(res.nickname).toBe('小南');\n});\n\ntest('问卷落库失败：本地继续，不阻断流程', async () => {\n  const { api } = loadApi(fail());\n  const res = await api.submitOnboard({ 4: '小南' });\n  expect(res.offline).toBe(true);\n  expect(res.nickname).toBe('小南');\n});\n\ntest('聊天：带上文走 xixiChat，回复透传', async () => {\n  const { api, calls } = loadApi(ok({ ok: true, reply: '我在听' }));\n  const res = await api.sendChatMessage('最近很累');\n  expect(calls[0].name).toBe('xixiChat');\n  expect(calls[0].data.action).toBe('chat');\n  expect(calls[0].data.history[calls[0].data.history.length - 1].content).toBe('最近很累');\n  expect(res.reply).toBe('我在听');\n  expect(res.crisis).toBe(false);\n});\n\ntest('聊天：模型失败回落本地回复池，不 reject', async () => {\n  const { api } = loadApi(fail());\n  const res = await api.sendChatMessage('最近很累');\n  expect(typeof res.reply).toBe('string');\n  expect(res.reply.length).toBeGreaterThan(10);\n  expect(res.offline).toBe(true);\n});\n\ntest('危机词本地先拦：不调云函数，直接返回危机态', async () => {\n  const { api, calls } = loadApi(ok({ ok: true, reply: 'x' }));\n  const res = await api.sendChatMessage('我不想活了');\n  expect(calls.length).toBe(0);\n  expect(res.crisis).toBe(true);\n  expect(res.reply).toContain('400-161-9995');\n});\n\ntest('报告：云端的数值迫切度被适配成 level + label', async () => {\n  const { api, calls } = loadApi(ok({\n    ok: true,\n    report: { emotions: ['焦虑'], conflict: '信任危机', goal: '稳住', urgency: 72, urgencyText: '', direction: '信任修复' }\n  }));\n  const res = await api.submitPrediagAnswers(['a', 'b']);\n  expect(calls[0].data.action).toBe('report');\n  expect(res.report.urgency.level).toBeCloseTo(0.72);\n  expect(res.report.urgency.label).toContain('尽快');\n  expect(res.report.direction).toBe('信任修复');\n});\n\ntest('报告：生成失败返回失败态，不拿演示内容冒充用户结果', async () => {\n  const { api } = loadApi(ok({ ok: false, err: 'BAD_REPORT_JSON' }));\n  const res = await api.submitPrediagAnswers(['a']);\n  expect(res.report).toBe(null);\n  expect(res.failed).toBe(true);\n});\n\ntest('报告：字段残缺同样视为失败', async () => {\n  const { api } = loadApi(ok({ ok: true, report: { emotions: ['焦虑'] } }));\n  const res = await api.submitPrediagAnswers(['a']);\n  expect(res.report).toBe(null);\n  expect(res.failed).toBe(true);\n});\n\ntest('问卷跳过称呼：不覆盖已保存的昵称', async () => {\n  const { api, calls } = loadApi(ok({ ok: true }));\n  await api.submitOnboard({ 0: ['伴侣沟通不顺'] });\n  expect('nickname' in calls[0].data.payload.profile).toBe(false);\n});\n\ntest('心情打卡：按真实日期写 moods 域', async () => {\n  const { api, calls } = loadApi(ok({ ok: true }));\n  await api.saveMood(2);\n  expect(calls[0].name).toBe('xixiData');\n  expect(calls[0].data.payload.moods[0].mood).toBe(2);\n  expect(calls[0].data.payload.moods[0].date).toMatch(/^\\d{4}-\\d{2}-\\d{2}$/);\n});\n\ntest('首页金句：优先用云端内容，缺失回落本地', async () => {\n  const cloud = loadApi(ok({ ok: true, data: { quotes: [{ text: '云端的句子', author: '西米' }] } }));\n  const r1 = await cloud.api.fetchDailyQuote();\n  expect(r1.text).toBe('云端的句子');\n\n  const empty = loadApi(ok({ ok: true, data: {} }));\n  const r2 = await empty.api.fetchDailyQuote();\n  expect(r2.text.length).toBeGreaterThan(4);\n  expect(r2.image).toContain('/images/quotes/');\n});\n\ntest('静态内容不依赖网络：题集、陪伴师、下单都本地返回', async () => {\n  const { api, calls } = loadApi(ok({ ok: true }));\n  const steps = await api.fetchOnboardQuestions();\n  expect(Array.isArray(steps)).toBe(true);\n  expect(steps.length).toBeGreaterThan(3);\n  const qs = await api.fetchPrediagQuestions();\n  expect(qs.length).toBe(5);\n  const list = await api.fetchCounselors();\n  expect(list.length).toBe(3);\n  const order = await api.createOrder('c1', '明天 10:00');\n  expect(order.orderId).toBeTruthy();\n  expect(order.payParams).toBe(null);\n  expect(calls.length).toBe(0);\n});\n\ntest('启动同步：心情历史落本地缓存，问卷称呼写回 store', async () => {\n  const store = {};\n  const { api } = (() => {\n    jest.resetModules();\n    const calls = [];\n    global.wx = {\n      cloud: { callFunction(o) { calls.push(o); o.success({ result: { ok: true, data: {\n        moods: [{ date: '2026-10-01', mood: 2 }],\n        profile: { answers: { 0: ['失眠、想太多'] }, nickname: '阿南' }\n      } } }); } },\n      getStorageSync: (k) => (k in store ? store[k] : ''),\n      setStorageSync: (k, v) => { store[k] = v; },\n      removeStorageSync: (k) => { delete store[k]; }\n    };\n    return { api: require(path.join(__dirname, '../../utils/api.js')), calls };\n  })();\n  const d = await api.syncCloud();\n  expect(d.moods.length).toBe(1);\n  expect(store.xixi_moods[0].mood).toBe(2);\n  const user = require(path.join(__dirname, '../../stores/user.js'));\n  expect(user.get('nickname')).toBe('阿南');\n  expect(user.get('obAnswers')[0][0]).toBe('失眠、想太多');\n});\n\ntest('启动同步：云端失败静默返回 null，不影响启动', async () => {\n  const { api } = loadApi(fail());\n  await expect(api.syncCloud()).resolves.toBe(null);\n});\n","tools/__tests__/domains.local.test.js":"/* 领域与演示适配器：演示数据必须自证、心情只认真实记录 */\nconst path = require('path');\n\nfunction fresh(modules) {\n  jest.resetModules();\n  const store = {};\n  global.wx = {\n    getStorageSync: (k) => (k in store ? store[k] : ''),\n    setStorageSync: (k, v) => { store[k] = v; },\n    removeStorageSync: (k) => { delete store[k]; },\n    getWindowInfo: () => ({ statusBarHeight: 20, windowHeight: 800 }),\n    getMenuButtonBoundingClientRect: () => ({ top: 24, height: 32 })\n  };\n  global.__store = store;\n  return modules.map(m => require(path.join(__dirname, '../..', m)));\n}\n\ntest('演示适配器：陪伴师带 demo 标记，且不含价格/评分/案例', async () => {\n  const [demo] = fresh(['utils/adapters/demo.js']);\n  const list = await demo.companions();\n  expect(list.length).toBeGreaterThan(0);\n  list.forEach(c => {\n    expect(c.demo).toBe(true);\n    expect(c.price).toBeUndefined();\n    expect(c.rating).toBeUndefined();\n    expect(c.cases).toBeUndefined();\n  });\n});\n\ntest('陪伴师详情按 id 返回对应的人', async () => {\n  const [companion] = fresh(['utils/domains/companion.js']);\n  const a = await companion.detail('c2');\n  const b = await companion.detail('c3');\n  expect(a.id).toBe('c2');\n  expect(b.id).toBe('c3');\n  expect(a.name).not.toBe(b.name);\n});\n\ntest('演示适配器：报告不伪造结果', async () => {\n  const [demo] = fresh(['utils/adapters/demo.js']);\n  const r = await demo.report();\n  expect(r.report).toBe(null);\n  expect(r.failed).toBe(true);\n});\n\ntest('心情：同日覆盖、按日期排序、上限内保留', () => {\n  const [mood] = fresh(['utils/domains/mood.js']);\n  let list = mood.merge([], { date: '2026-10-01', mood: 1 });\n  list = mood.merge(list, { date: '2026-10-02', mood: 2 });\n  list = mood.merge(list, { date: '2026-10-01', mood: 4 });\n  expect(list).toEqual([{ date: '2026-10-01', mood: 4 }, { date: '2026-10-02', mood: 2 }]);\n});\n\ntest('心情：空数据时日历没有伪记录', () => {\n  const [mood] = fresh(['utils/mood.js']);\n  const cal = mood.calendar();\n  const filled = Object.keys(cal.hist).filter(d => cal.hist[d] !== null);\n  expect(filled.length).toBe(0);\n  expect(cal.cells.every(c => c.pad || c.mi === null)).toBe(true);\n});\n\ntest('心情：连续天数按真实记录计算，今天没打不打断', () => {\n  const [mood] = fresh(['utils/mood.js']);\n  const now = new Date();\n  const key = (offset) => {\n    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - offset);\n    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);\n  };\n  global.wx.setStorageSync('xixi_moods', [\n    { date: key(1), mood: 1 },\n    { date: key(2), mood: 2 }\n  ]);\n  expect(mood.streak()).toBe(2);\n  global.wx.setStorageSync('xixi_moods', [{ date: key(0), mood: 0 }]);\n  expect(mood.streak()).toBe(1);\n});\n\ntest('心情：周视图跨月不出现不存在的日期', () => {\n  const [mood] = fresh(['utils/mood.js']);\n  const cal = mood.calendar();\n  cal.week.forEach(w => {\n    if (w.d !== '') expect(w.d >= 1 && w.d <= 31).toBe(true);\n  });\n  expect(cal.weekCap).not.toMatch(/月32日/);\n});\n","tools/__tests__/ui-frame.test.js":"/* 骨架度量：给定设备上报值，产出稳定的顶部/底部留白 */\nconst path = require('path');\n\nfunction load(wxStub) {\n  jest.resetModules();\n  global.wx = wxStub;\n  return require(path.join(__dirname, '../../utils/ui.js'));\n}\n\ntest('刘海屏：状态栏 + 胶囊推算导航带，内容起点下移', () => {\n  const ui = load({\n    getWindowInfo: () => ({ statusBarHeight: 47, screenHeight: 844, windowHeight: 844, safeArea: { bottom: 810 } }),\n    getMenuButtonBoundingClientRect: () => ({ top: 51, height: 32, bottom: 83 })\n  });\n  const f = ui.frame();\n  expect(f.statusBar).toBe(47);\n  expect(f.nav).toBe(40);           // (51-47)*2 + 32\n  expect(f.top).toBe(87);\n  expect(f.contentTop).toBe(99);\n  expect(f.bottom).toBe(34);        // 844 - 810\n});\n\ntest('无胶囊信息时回落 44 的导航带，不抛错', () => {\n  const ui = load({\n    getWindowInfo: () => ({ statusBarHeight: 20, windowHeight: 667 }),\n    getMenuButtonBoundingClientRect: () => { throw new Error('no menu'); }\n  });\n  const f = ui.frame();\n  expect(f.nav).toBe(44);\n  expect(f.top).toBe(64);\n  expect(f.bottom).toBe(0);\n});\n\ntest('老接口：没有 getWindowInfo 时用 getSystemInfoSync', () => {\n  const ui = load({\n    getSystemInfoSync: () => ({ statusBarHeight: 24, windowHeight: 780, safeArea: { bottom: 780 } })\n  });\n  const f = ui.frame();\n  expect(f.statusBar).toBe(24);\n  expect(f.top).toBe(68);\n  expect(f.bottom).toBe(0);\n});\n","tools/__tests__/x-btn.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-btn', () => {\n  test('renders and behaves correctly', () => {\nlet fired = 0;\nconst comp = simulate.render(X_BTN_ID, { type: 'primary', block: true, disabled: true });\ncomp.addEventListener('tap', () => fired++);\ncomp.querySelector('.btn').dispatchEvent('tap');\nexpect(fired).toBe(0);\nexpect(comp.dom.innerHTML).toContain('width:100%');\nconst comp2 = simulate.render(X_BTN_ID, { type: 'primary' });\nexpect(comp2.dom.innerHTML).toContain('btn-primary');\n\n  });\n});\n","tools/__tests__/x-card.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-card', () => {\n  test('renders and behaves correctly', () => {\nconst comp = simulate.render(X_CARD_ID, { rise: 3 });\nexpect(comp.dom.innerHTML).toContain('rise');\nexpect(comp.dom.innerHTML).toContain('d3');\n\n  });\n});\n","tools/__tests__/x-icon.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-icon', () => {\n  test('renders and behaves correctly', () => {\nconst comp = simulate.render(X_ICON_ID, { name: 'ic30f', size: 48 });\nexpect(comp.dom.innerHTML).toContain('ic30f');\nexpect(comp.dom.innerHTML).toContain('width:48');\n\n  });\n});\n","tools/__tests__/x-msg.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-msg', () => {\n  test('renders and behaves correctly', () => {\nconst ai = simulate.render(X_MSG_ID, { role: 'ai', text: '我在听', tags: ['焦虑'], mem: true });\nexpect(ai.dom.innerHTML).toContain('我在听');\nexpect(ai.dom.innerHTML).toContain('emo-tags');\nexpect(ai.dom.innerHTML).toContain('已引用你的档案记忆');\nconst user = simulate.render(X_MSG_ID, { role: 'user', text: '我累了' });\nexpect(user.dom.innerHTML).toContain('我累了');\nexpect(user.dom.innerHTML).not.toContain('avatar-ai');\nconst typing = simulate.render(X_MSG_ID, { role: 'ai', typing: true });\nexpect(typing.dom.innerHTML).toContain('--typing');\n\n  });\n});\n","tools/__tests__/x-navbar.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-navbar', () => {\n  test('renders and behaves correctly', () => {\nconst comp = simulate.render(X_NAVBAR_ID, { title: '咨询师详情' });\nexpect(comp.dom.innerHTML).toContain('咨询师详情');\nexpect(comp.dom.innerHTML).toContain('pg-back');\nexpect(comp.dom.innerHTML).toContain('top-fade');\nconst dark = simulate.render(X_NAVBAR_ID, { title: '失眠关怀专区', dark: true });\nexpect(dark.dom.innerHTML).toContain('--dark');\n\n  });\n});\n","tools/__tests__/x-sheet.test.js":"/* 组件单测（官方 miniprogram-simulate） */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-sheet', () => {\n  test('renders and behaves correctly', () => {\n    let closed = 0;\n    const comp = simulate.render(X_SHEET_ID, { show: false });\n    expect(comp.dom.innerHTML).not.toContain('--sheet main--show');\n    comp.setData({ show: true });\n    expect(comp.dom.innerHTML).toContain('--sheet main--show');\n    comp.addEventListener('close', () => closed++);\n    comp.instance.onClose();   /* bindtap 同一入口，行为等价 */\n    expect(closed).toBe(1);\n  });\n});\n","tools/check-assets.js":"/* 包内容物资产断言：上传前的硬门。命中任一即退出码 1。\n * 用法：node tools/check-assets.js [小程序目录，默认仓库根]\n *\n * 1. 包内禁止 .webp —— iOS 真机不渲染 webp（主线 2026-10-11 三连踩定案：\n *    提审线曾带 27 张包内 webp，真机走查即成片空白图）。网络图/包内图一律 jpg/png。\n * 2. 代码引用的本地图片必须真实存在 —— 引用悬空在开发者工具里常静默空白，\n *    真机才暴露；此断言把「空白图」拦在上传前。\n */\nconst fs = require('fs');\nconst path = require('path');\n\nconst ROOT = path.resolve(process.argv[2] || path.join(__dirname, '..'));\n\nconst cfg = JSON.parse(fs.readFileSync(path.join(ROOT, 'project.config.json'), 'utf8'));\nconst ignores = ((cfg.packOptions || {}).ignore || [])\n  .filter((it) => it.type === 'folder')\n  .map((it) => it.value.replace(/\\/$/, ''));\n\nfunction walk(dir, out) {\n  for (const name of fs.readdirSync(dir)) {\n    if (name === '.git' || name === 'node_modules') continue;\n    const abs = path.join(dir, name);\n    const rel = path.relative(ROOT, abs);\n    if (ignores.some((ig) => rel === ig || rel.startsWith(ig + '/'))) continue;\n    const st = fs.statSync(abs);\n    if (st.isDirectory()) walk(abs, out);\n    else out.push({ rel, abs });\n  }\n  return out;\n}\n\nconst files = walk(ROOT, []);\nconst problems = [];\n\n/* 1. webp 禁令 */\nconst webp = files.filter((f) => /\\.webp$/i.test(f.rel));\nfor (const f of webp) problems.push(`${f.rel}: 包内 webp（iOS 真机不渲染，一律 jpg/png）`);\n\n/* 2. 代码引用的本地图片必须存在（wxml/js/wxss 全扫；跳过 {{}} 数据绑定命中） */\nconst imgRefs = [];\nfor (const f of files) {\n  if (!/\\.(wxml|js|wxss)$/.test(f.rel)) continue;\n  const src = fs.readFileSync(f.abs, 'utf8');\n  for (const m of src.matchAll(/['\"(](\\/images\\/[^'\")?]+?\\.(?:jpg|jpeg|png|webp))['\")]/g)) {\n    if (m[1].includes('{{')) continue; /* 数据绑定路径静态不可判，交由运行时 */\n    imgRefs.push({ from: f.rel, to: m[1] });\n  }\n  /* 网络图 webp 同罪（字面量可查；动态拼接走人工真机走查） */\n  for (const m of src.matchAll(/https?:\\/\\/[^'\"\\s)]+?\\.webp/gi)) {\n    problems.push(`${f.rel}: 引用网络 webp ${m[0]}`);\n  }\n}\nfor (const r of imgRefs) {\n  if (!fs.existsSync(path.join(ROOT, r.to))) problems.push(`${r.from}: 引用不存在的图片 ${r.to}`);\n}\n\n/* 3. 动态拼接的图片集必须有完整成员（静态正则查不到拼接点——双轴审查盲区实证：\n *    quotes q1..q8 全仓唯一引用是 `'/images/quotes/q' + n + '.jpg'`） */\nconst DYNAMIC_SETS = [{ prefix: \"/images/quotes/q\", count: 8, ext: \".jpg\" }]; /* 与 utils/domains/content.js 的 day%8 拼接双硬编码——改 8 两处同步 */\nfor (const s of DYNAMIC_SETS) {\n  for (let i = 1; i <= s.count; i++) {\n    const p = `${s.prefix}${i}${s.ext}`;\n    if (!fs.existsSync(path.join(ROOT, p))) problems.push(`动态图片集缺成员 ${p}`);\n  }\n}\n\nif (problems.length) {\n  console.error('✗ 资产断言未通过：');\n  for (const p of problems) console.error('  - ' + p);\n  process.exit(1);\n}\nconsole.log(`✓ 资产断言通过（0 webp；${imgRefs.length} 处引用 + ${DYNAMIC_SETS.length} 组动态集全部存在）`);\n","tools/check-demo-leak.js":"/* 演示态泄漏断言：上传前的硬门。命中任一即退出码 1。\n * 用法：node tools/check-demo-leak.js [小程序目录，默认仓库根]\n *\n * 口径（对照项目 P0 教训：提审包静默携带演示数据/虚假文案）：\n *  1. 演示适配器（utils/adapters/demo.js）只能被 utils/domains/ 引用；\n *    页面/组件/app 直连演示数据即泄漏。诚实演示态的口径是「数据层带 demo 标记，\n *    页面如实标注」，不是让页面各取所需。\n *  2. 零容忍字符串：任何「不会产生真实扣款」类支付免责文案与「测试环境/测试包」\n *    标记不得出现在包内任何文件——它们只该存在于仓库外的构建口径里。\n *    注意：「演示」「示例」本身是设计内的诚实标注（示例名单、示例资料），\n *    不在本断言词表；词表只收「泄漏特征」，不收「诚实标注」。\n */\nconst fs = require('fs');\nconst path = require('path');\n\nconst ROOT = path.resolve(process.argv[2] || path.join(__dirname, '..'));\n/* 目录级口径：utils/adapters/ 下任何演示适配器只许被 utils/domains/ 引用——\n * 按文件名单点白名单可被「克隆 demo2.js」绕过（双轴审查反例） */\nconst DEMO_ADAPTER_DIR = /^utils\\/adapters\\//;\nconst DEMO_HOSTS = /^utils\\/domains\\//;\nconst BANNED = ['不会产生真实扣款', '不会真实扣款', '演示版，不会', '测试环境', '测试包',\n  '不产生任何费用', '不产生费用', '仅供体验'];\n/* 「假数据」只许出现在演示适配器目录自己的注释里 */\nconst FAKE_DATA_ALLOW = /^utils\\/adapters\\//;\nconst SKIP_DIRS = new Set(['.git', 'node_modules', 'tools', 'docs', 'tests']);\n\nfunction walk(dir, out) {\n  for (const name of fs.readdirSync(dir)) {\n    if (SKIP_DIRS.has(name)) continue;\n    const abs = path.join(dir, name);\n    const st = fs.statSync(abs);\n    if (st.isDirectory()) walk(abs, out);\n    else if (/\\.(wxml|js|json|wxss)$/.test(name)) out.push({ rel: path.relative(ROOT, abs), abs });\n  }\n  return out;\n}\n\nconst problems = [];\nconst files = walk(ROOT, []);\n\nfor (const f of files) {\n  const rel = f.rel.replace(/\\\\/g, '/');\n  const src = fs.readFileSync(f.abs, 'utf8');\n  if (/\\.(js)$/.test(rel)) {\n    for (const m of src.matchAll(/require\\(\\s*['\"]([^'\"]+)['\"]\\s*\\)|from\\s+['\"]([^'\"]+)['\"]/g)) {\n      const spec = (m[1] || m[2] || '').replace(/^\\.\\//, '');\n      const resolved = spec.startsWith('.') ? path.posix.normalize(path.posix.join(path.posix.dirname(rel), spec)) : spec;\n      if (DEMO_ADAPTER_DIR.test(resolved.replace(/\\.js$/, '')) && !DEMO_HOSTS.test(rel)) {\n        problems.push(`${rel}: 直连演示适配器（utils/adapters/* 只能经 utils/domains/ 取数）`);\n      }\n    }\n  }\n  for (const w of BANNED) {\n    if (src.includes(w)) problems.push(`${rel}: 命中泄漏文案「${w}」`);\n  }\n  if (!FAKE_DATA_ALLOW.test(rel) && src.includes('假数据')) {\n    problems.push(`${rel}: 命中「假数据」（只许在演示适配器自身出现）`);\n  }\n}\n\nif (problems.length) {\n  console.error('✗ 演示态泄漏断言未通过：');\n  for (const p of problems) console.error('  - ' + p);\n  process.exit(1);\n}\nconsole.log(`✓ 演示态泄漏断言通过（扫描 ${files.length} 文件）`);\n","tools/check-redline.js":"/* 红线检查：上传前的硬门。命中任一即退出码 1。\n * 用法：node tools/check-redline.js [小程序目录，默认仓库根]\n *\n * 判定沿用后端既有红线：\n *  1. 用户可见代码中禁医疗词：诊断 / 治疗 / 治愈 / 康复 / 症状 / 患者\n *  2. 不出现「心理咨询」「咨询师」等专业身份宣称\n *  3. 危机弹卡零商业化：不得含陪伴师列表、会员、付费入口，必须有热线与拨号动作\n */\nconst fs = require('fs');\nconst path = require('path');\n\nconst ROOT = path.resolve(process.argv[2] || path.join(__dirname, '..'));\nconst BANNED = ['诊断', '治疗', '治愈', '康复', '症状', '患者'];\n/* 英文同罪（P0-2 教训：词表只扫中文放过过 PRE-DIAGNOSIS）——统一小写比对 */\nconst BANNED_EN = ['diagnosis', 'therapy', 'patient', 'clinic', 'symptom'];\nconst IDENTITY = ['心理咨询', '咨询师', '真人咨询'];\nconst BRAND = ['西西']; // 品牌名已统一为西米，出现旧名即视为漂移\nconst SKIP_DIRS = new Set(['.git', 'node_modules', 'tools', 'docs', 'tests']);\n\nfunction walk(dir, out) {\n  for (const name of fs.readdirSync(dir)) {\n    if (SKIP_DIRS.has(name)) continue;\n    const abs = path.join(dir, name);\n    const st = fs.statSync(abs);\n    if (st.isDirectory()) walk(abs, out);\n    else if (/\\.(wxml|js|json|wxss)$/.test(name)) out.push(abs);\n  }\n  return out;\n}\n\nconst problems = [];\nconst files = walk(ROOT, []);\n\nfor (const abs of files) {\n  const rel = path.relative(ROOT, abs);\n  const src = fs.readFileSync(abs, 'utf8');\n  for (const w of BANNED.concat(IDENTITY).concat(BRAND)) {\n    if (src.includes(w)) problems.push(`${rel}: 命中「${w}」`);\n  }\n  const lower = src.toLowerCase();\n  for (const w of BANNED_EN) {\n    if (lower.includes(w)) problems.push(`${rel}: 命中英文红线「${w}」`);\n  }\n}\n\n/* 危机弹卡：所有带危机卡的页面同跑同一套断言（content 页新增同款卡后纳入） */\nfunction checkCrisisCard(rel) {\n  const abs = path.join(ROOT, rel);\n  if (!fs.existsSync(abs)) {\n    problems.push(rel + ' 不存在，无法校验危机弹卡');\n    return;\n  }\n  const wxml = fs.readFileSync(abs, 'utf8');\n  const idx = wxml.indexOf('crisis-card');\n  if (idx < 0) {\n    problems.push(rel + ' 找不到危机弹卡');\n    return;\n  }\n  const block = wxml.slice(idx);\n  for (const bad of ['consultants', 'membership', 'payConsult', 'counselors']) {\n    if (block.includes(bad)) problems.push(rel + ' 危机弹卡内含商业化/导流入口「' + bad + '」');\n  }\n  if (!/callHotline/.test(block)) problems.push(rel + ' 危机弹卡缺少拨号动作 callHotline');\n  if (!/hotline/.test(block) && !/热线/.test(block)) problems.push(rel + ' 危机弹卡未展示热线');\n}\ncheckCrisisCard('pages/chat/chat.wxml');\ncheckCrisisCard('pages/content/content.wxml');\n\nif (problems.length) {\n  console.error('✗ 红线检查未通过：');\n  for (const p of problems) console.error('  - ' + p);\n  process.exit(1);\n}\nconsole.log(`✓ 红线检查通过（扫描 ${files.length} 文件）`);\n","tools/check-size.js":"/* 包体积检查：按小程序上传口径统计（排除 packOptions.ignore 的 folder 型与 .git），上限 2MB。\n * file 型 ignore（RELEASE.md/package.json 等）刻意计入 = 宁多算不少算（二轮双轴确认方向安全）。\n * 用法：node tools/check-size.js [目录，默认仓库根]\n */\nconst fs = require('fs');\nconst path = require('path');\n\nconst ROOT = path.resolve(process.argv[2] || path.join(__dirname, '..'));\nconst LIMIT = 2 * 1024 * 1024;\n\nconst cfg = JSON.parse(fs.readFileSync(path.join(ROOT, 'project.config.json'), 'utf8'));\nconst ignores = ((cfg.packOptions || {}).ignore || [])\n  .filter((it) => it.type === 'folder')\n  .map((it) => it.value.replace(/\\/$/, ''));\n\nfunction walk(dir, out) {\n  for (const name of fs.readdirSync(dir)) {\n    if (name === '.git' || name === 'node_modules') continue;\n    const rel = dir === ROOT ? name : path.relative(ROOT, path.join(dir, name));\n    const abs = path.join(dir, name);\n    if (ignores.some((ig) => rel === ig || rel.startsWith(ig + '/'))) continue;\n    const st = fs.statSync(abs);\n    if (st.isDirectory()) walk(abs, out);\n    else out.push({ rel, size: st.size });\n  }\n  return out;\n}\n\nconst files = walk(ROOT, []);\nconst total = files.reduce((s, f) => s + f.size, 0);\nconst top = files.slice().sort((a, b) => b.size - a.size).slice(0, 10);\nconst kb = (n) => (n / 1024).toFixed(0);\n\nconsole.log(`包体积: ${kb(total)} KB / 上限 ${kb(LIMIT)} KB（${files.length} 文件）`);\nconsole.log(`忽略目录: ${ignores.join(', ') || '无'}`);\nconsole.log('最大 10 个文件:');\nfor (const f of top) console.log(`  ${kb(f.size).padStart(5)} KB  ${f.rel}`);\n\nif (total > LIMIT) {\n  console.error(`✗ 超过上限 ${kb(total - LIMIT)} KB`);\n  process.exit(1);\n}\nconsole.log('✓ 低于上限');\n","tools/probe-runtime.js":"/* 运行时走查探针：逐页落地 + 截图 + 骨架/数据断言（发现循环的固定工具，勿再手搭）。\n * 前置：`cli auto --project <本目录> --auto-port 9500` 开自动化会话。\n * 用法：NODE_PATH=/tmp/mpci/node_modules PORT=9500 node tools/probe-runtime.js\n * 说明：只读走查；截图落 SHOTS（默认 /tmp/shots）。交互探针按票面需求临时扩展，\n * 沉淀时收敛进本文件（来源工单写注释）——出处：pre-submit-r1 票 30/31-34 三轮发现循环。\n */\nconst automator = require('miniprogram-automator');\nconst fs = require('fs');\nconst path = require('path');\nconst sleep = ms => new Promise(r => setTimeout(r, ms));\n\nconst PORT = process.env.PORT || '9500';\nconst SHOTS = process.env.SHOTS || '/tmp/shots';\nconst PAGES = [\n  ['launch', '/pages/launch/launch', 2600],\n  ['onboard', '/pages/onboard/onboard', 2200],\n  ['summary', '/pages/summary/summary', 1800],\n  ['home', '/pages/home/home', 2600],\n  ['chat', '/pages/chat/chat', 4200],\n  ['prediag', '/pages/prediag/prediag', 1800],\n  ['report', '/pages/report/report', 2000],\n  ['consultants', '/pages/consultants/consultants', 1800],\n  ['cdetail', '/pages/cdetail/cdetail', 1800],\n  ['sleep', '/pages/sleep/sleep', 1800],\n  ['content', '/pages/content/content', 2200],\n  ['me', '/pages/me/me', 2200],\n  ['moodcal', '/pages/moodcal/moodcal', 1800],\n  ['profile', '/pages/profile/profile', 1800],\n  ['privacy', '/pages/privacy/privacy', 1500],\n];\n\n(async () => {\n  const mp = await automator.connect({ wsEndpoint: `ws://127.0.0.1:${PORT}` });\n  fs.mkdirSync(SHOTS, { recursive: true });\n  let pass = 0, fail = 0;\n  const log = (ok, name, msg) => { console.log(ok ? '✓' : '✗', name, msg || ''); ok ? pass++ : fail++; };\n\n  for (const [name, route, wait] of PAGES) {\n    try {\n      const page = await mp.reLaunch(route);\n      await sleep(wait);\n      const cur = await mp.currentPage();\n      /* launch 语义=按 onboarding 状态分流（fresh→onboard，老用户→home），不算落地失败 */\n      const landed = cur && cur.path;\n      const okLanding = landed === route.slice(1) ||\n        (name === 'launch' && (landed === 'pages/onboard/onboard' || landed === 'pages/home/home'));\n      if (!okLanding) { log(false, name, '落地失败: ' + landed); continue; }\n      const shot = path.join(SHOTS, `probe-${name}.png`);\n      await mp.screenshot({ path: shot });\n      /* 骨架断言：behavior 生命周期已死，页面必须自己调 syncFrame（票 30）——值不该再是 0 */\n      const ft = await cur.data('frameTop');\n      if (!ft) log(false, name, 'frameTop=0（骨架未接线）');\n      else log(true, name, `frameTop=${ft} → ${path.basename(shot)}`);\n    } catch (e) {\n      log(false, name, e.message.slice(0, 60));\n    }\n  }\n\n  /* 数据残留断言：profile 删除清单之外的 xixi_* 键（票面：三轮 round-4 扩展） */\n  try {\n    await mp.reLaunch('/pages/me/me');\n    await sleep(1200);\n    const keys = await mp.evaluate(() => JSON.stringify(wx.getStorageInfoSync().keys));\n    const list = JSON.parse(keys).filter(k => k.indexOf('xixi_') === 0);\n    console.log('storage xixi_* keys:', list.join(', ') || '(none)');\n  } catch (e) {\n    log(false, 'storage', e.message.slice(0, 60));\n  }\n\n  await mp.disconnect();\n  console.log(`\\n${pass} 通过 / ${fail} 失败`);\n  process.exit(fail ? 1 : 0);\n})().catch(e => { console.error('FATAL:', e.message); process.exit(1); });\n","tools/regression.js":"/* ============================================================\n * 全流程回归走查（项目资产，勿放 /tmp）\n * 用法：先 `cli auto --project <root> --auto-port <PORT>` 开自动化，\n *       然后 PORT=9500 node tools/regression.js\n * 连接后会校验页面里注入的 BUILD_ID，防止\"测的不是改的\"\n * ============================================================ */\nconst automator = require('miniprogram-automator');\nconst fs = require('fs');\nconst path = require('path');\nconst sleep = ms => new Promise(r => setTimeout(r, ms));\n\nconst ROOT = path.join(__dirname, '..');\nconst PORT = process.env.PORT || '9500';\nconst SHOTS = process.env.SHOTS || '/tmp/shots';\n\n/* 构建指纹：改动任何页面文件后手动 +1，或让 CI 注入。\n * 注意：相对 require 按本文件所在目录（tools/）解析，必须写 ../（双轴审查 P1） */\nconst BUILD_ID = require('../BUILD_ID.js');\n\n(async () => {\n  const mp = await automator.connect({ wsEndpoint: `ws://127.0.0.1:${PORT}` });\n  fs.mkdirSync(SHOTS, { recursive: true });\n  let pass = 0, fail = 0;\n\n  const shot = async name => {\n    await sleep(600);\n    try { await mp.screenshot({ path: `${SHOTS}/${name}.png` }); pass++; console.log('📷', name); }\n    catch (e) { fail++; console.log('✗', name, e.message.slice(0, 50)); }\n  };\n  const cur = async () => (await mp.pageStack()).map(p => p.path).pop();\n\n  /* 指纹校验：往任意页 evaluate 读 BUILD_ID（app.js 挂的） */\n  try {\n    const injected = await mp.evaluate(() => getApp().BUILD_ID);\n    if (injected !== BUILD_ID) {\n      console.error(`✗ 构建指纹不一致！IDE 运行的是 ${injected}，本地是 ${BUILD_ID}。请重启 IDE 实例再测。`);\n      process.exit(2);\n    }\n    console.log('✓ 构建指纹一致:', BUILD_ID);\n  } catch (e) {\n    console.error('✗ 无法读取构建指纹（IDE 实例异常或 BUILD_ID 未注入）:', e.message.slice(0, 60));\n    process.exit(2);\n  }\n\n  console.log('起点:', await cur());\n  await shot('00-onboard');\n  /* …流程同 /tmp 版 walk.js：问卷→汇总→tab 页→子页…（保持人工可读） */\n  await mp.disconnect();\n  console.log(`\\n${pass} 通过 / ${fail} 失败`);\n  process.exit(fail ? 1 : 0);\n})().catch(e => { console.error('FATAL:', e.message); process.exit(1); });\n","tools/release.js":"/* 预览 / 上传：使用微信代码上传密钥（miniprogram-ci）。\n * 用法（密钥路径必须从环境变量传入，禁止写进仓库）：\n *   XWX_KEY=/path/to/private.key node tools/release.js preview\n *   XWX_KEY=/path/to/private.key node tools/release.js upload [版本号] [说明]\n */\nconst path = require('path');\nconst ci = require('miniprogram-ci');\n\nconst ROOT = path.resolve(__dirname, '..');\nconst APPID = 'wxacdf79aa2ccf2677';\nconst KEY = process.env.XWX_KEY || '';\n\nconst cmd = process.argv[2] || 'preview';\nif (!KEY) {\n  console.error('缺少 XWX_KEY（代码上传密钥路径）');\n  process.exit(1);\n}\n\nconst project = new ci.Project({\n  appid: APPID,\n  type: 'miniProgram',\n  projectPath: ROOT,\n  privateKeyPath: KEY,\n  ignores: ['node_modules/**/*', 'tools/**/*']\n});\n\nconst onProgressUpdate = (task) => {\n  const m = task.message || '';\n  if (m) console.log('· ' + m);\n};\n\nif (cmd === 'preview') {\n  ci.preview({\n    project,\n    desc: 'release/1007 预览',\n    setting: { es6: true, minify: true, urlCheck: false },\n    qrcodeFormat: 'image',\n    qrcodeOutputDest: path.join(ROOT, 'preview-qrcode.jpg'),\n    onProgressUpdate\n  }).then(() => console.log('✓ 预览二维码已生成：preview-qrcode.jpg'))\n    .catch((e) => { console.error('✗ 预览失败：', e && e.message); process.exit(1); });\n} else if (cmd === 'upload') {\n  const version = process.argv[3] || '1.0.0';\n  const desc = process.argv[4] || '情绪自助陪伴工具，非医疗服务；本版不含支付与真人预约';\n  ci.upload({\n    project,\n    version,\n    desc,\n    setting: { es6: true, minify: true, urlCheck: false },\n    onProgressUpdate\n  }).then(() => console.log('✓ 已上传体验版 ' + version))\n    .catch((e) => { console.error('✗ 上传失败：', e && e.message); process.exit(1); });\n} else {\n  console.error('未知命令：' + cmd + '（preview | upload）');\n  process.exit(1);\n}\n","utils/adapters/cloud.js":"/* 云端适配器：把领域动作翻译成云函数调用。不做兜底、不藏错误。 */\nconst { callCloud } = require('../transport');\nconst cfg = require('../config');\n\nfunction saveProfile(profile, baseTs) {\n  return callCloud('xixiData', { action: 'push', baseTs: baseTs, payload: { profile: profile } });\n}\n\nfunction pull() {\n  return callCloud('xixiData', { action: 'pull' });\n}\n\nfunction chat(payload) {\n  return callCloud('xixiChat', Object.assign({ action: 'chat' }, payload), cfg.LLM_TIMEOUT);\n}\n\nfunction report(answers, extra) {\n  return callCloud('xixiChat', Object.assign({ action: 'report', answers: answers }, extra || {}), cfg.LLM_TIMEOUT);\n}\n\nfunction content() {\n  return callCloud('xixiSync', { action: 'get' });\n}\n\nmodule.exports = { saveProfile, pull, chat, report, content };\n","utils/adapters/demo.js":"/* 演示适配器：所有假数据只能从这里出来，且结果显式带 demo 标记。 */\nconst { delay } = require('../transport');\n\nconst OB_STEPS = [\n  { type: 'multi', max: 3, label: '当前困扰 · 多选，最多 3 项', title: '最近，哪些事让你想找人说说？', sub: '选最接近的就好，之后可改。', skip: '暂时不想说', note: '我在听。',\n    opts: ['伴侣沟通不顺', '婚姻出现变化', '对关系感到不安', '家庭/亲子压力', '情绪起伏大', '工作生活压力大', '失眠、想太多', '孤独、没人理解', '想更了解自己', '只是想说说话'] },\n  { type: 'multi', max: 2, label: '陪伴偏好 · 多选，最多 2 项', title: '你希望西米怎么陪你？', sub: '没有标准答案，我会边聊边调。', skip: '还不确定，先聊聊', note: '慢慢来。',\n    opts: ['先听我说完', '帮我把事理清楚', '帮我看见真实感受', '一起想想怎么办', '提醒我注意安全与边界', '需要时联系真人陪伴师', '还不确定，先聊聊'] },\n  { type: 'single', label: '关系阶段 · 单选，可跳过', title: '你目前大致处在哪个阶段？', sub: '只用来更好理解你，不会替你做关系决定。', skip: '暂时不想说', note: '谢谢你愿意说。',\n    opts: ['单身 / 暂无稳定关系', '恋爱 / 稳定交往', '已婚 / 共同生活', '分居、离婚或关系变动中', '情况比较复杂', '暂时不想说'] },\n  { type: 'single', label: '当前情绪 · 单选', title: '此刻感受更接近？', sub: '选最接近的一项即可。', skip: '说不清楚', note: '辛苦了。',\n    opts: ['比较平静', '有些委屈', '焦虑不安', '生气烦躁', '疲惫无力', '难过想哭', '感到绝望', '说不清楚'] },\n  { type: 'name', label: '怎么称呼 · 可选', title: '我可以怎么叫你？', sub: '不用真名，只用于陪伴称呼。', skip: '暂时不设置', note: '很高兴认识你。' }\n];\n\nconst PREDIAG_QUESTIONS = [\n  { q: '在给你看示例陪伴师名单之前，我想先了解几个关键信息。\\n\\n你们目前的关系状态是怎样的？', opts: ['正在冷战', '刚出现信任危机', '已经分居', '其他情况'] },\n  { q: '谢谢你愿意告诉我这些。这件事大概发生多久了？', opts: ['一周内', '一个月内', '半年以内', '已经超过半年'] },\n  { q: '嗯，我明白了。那你现在最困扰、最想解决的问题是什么？', opts: ['信任崩塌走不出来', '情绪内耗很严重', '担心影响孩子', '不知道该不该继续'] },\n  { q: '好的。你希望通过这次梳理，达到什么样的目标？', opts: ['修复这段关系', '看清方向再做决定', '先让自己情绪稳定', '学会保护自己和孩子'] },\n  { q: '最后一个问题——之前有没有尝试过其他方式来解决？', opts: ['自己看书调整过', '找朋友倾诉过', '做过情绪疏导', '还没有尝试过'] }\n];\n\nconst CHAT_REPLIES = [\n  '嗯，我在听。这种反反复复的猜测最消耗人了——你一个人扛了这么久，真的很不容易。\\n\\n如果此刻只做一件让自己松一口气的小事，你会想到什么？',\n  '能感觉到你说这些的时候，心里是又委屈又疲惫的。任何人在你的处境里，都会有这样的感受。\\n\\n我们先把「他有没有」放一放。你有多久没有好好睡过一觉、好好吃过一顿饭了？',\n  '谢谢你愿意把这些说给我听。能看出来，你心里其实已经在慢慢有答案了，只是还需要一点力量去确认它。\\n\\n如果下周的今天，你希望自己的生活是什么样子？'\n];\n\n/* 陪伴师：演示名单。demo 标记是数据的一部分，页面据此展示「演示」。 */\nconst COMPANIONS = [\n  { id: 'c1', demo: true, name: '沈若云', avatar: '/images/avatar-c1.jpg', badge: '示例',\n    title: '情绪陪伴 · 婚姻沟通方向', tags: ['出轨创伤', '信任修复'], recommend: true },\n  { id: 'c2', demo: true, name: '林晚', avatar: '/images/avatar-c2.jpg',\n    title: '婚姻家庭陪伴 · 夫妻沟通', tags: ['夫妻沟通', '情绪疗愈'] },\n  { id: 'c3', demo: true, name: '陈静姝', avatar: '/images/avatar-c3.jpg',\n    title: '情绪陪伴 · 女性成长', tags: ['婚姻危机', '女性成长'] }\n];\n\nconst COMPANION_DETAIL = {\n  c1: { background: '示例资料：专注出轨创伤修复与夫妻信任重建。', tags: ['出轨创伤', '信任修复', '夫妻沟通', '情绪稳定'] },\n  c2: { background: '示例资料：擅长夫妻沟通与情绪陪伴。', tags: ['夫妻沟通', '情绪疗愈'] },\n  c3: { background: '示例资料：关注婚姻危机中的女性成长。', tags: ['婚姻危机', '女性成长'] }\n};\n\nconst QUOTES = [\n  ['不必把每个人都请进你的世界，留一点空间给自己。', '西米', 'q1'],\n  ['先照顾好自己，才有力气照顾关系。', '西米', 'q2'],\n  ['温柔不是妥协，是见过风雨之后的选择。', '西米', 'q3'],\n  ['你照顾了所有人，也要记得被自己照顾。', '西米', 'q4'],\n  ['真正的强大，是允许自己偶尔不强大。', '西米', 'q5'],\n  ['把日子过热一点，心就不那么冷了。', '西米', 'q6'],\n  ['把日子过成自己喜欢的样子，什么时候开始都不晚。', '西米', 'q7'],\n  ['愿你成为自己的太阳，无需凭借谁的光。', '西米', 'q8']\n];\n\nmodule.exports = {\n  OB_STEPS,\n  PREDIAG_QUESTIONS,\n  CHAT_REPLIES,\n  COMPANIONS,\n  COMPANION_DETAIL,\n  QUOTES,\n\n  onboardQuestions: () => delay(100, OB_STEPS),\n  prediagQuestions: () => delay(100, PREDIAG_QUESTIONS),\n  chatReply: () => delay(1300, { reply: CHAT_REPLIES[Math.floor(Math.random() * CHAT_REPLIES.length)], demo: true }),\n  report: () => delay(600, { report: null, failed: true, demo: true }),\n  companions: () => delay(200, COMPANIONS),\n  companionDetail: (id) => {\n    const base = COMPANIONS.find(c => c.id === id) || COMPANIONS[0];\n    const extra = COMPANION_DETAIL[base.id] || COMPANION_DETAIL.c1;\n    return delay(200, Object.assign({}, base, { background: extra.background }, { tags: extra.tags }));\n  },\n  quote: (dayOfYear) => {\n    const q = QUOTES[dayOfYear % QUOTES.length];\n    return delay(100, { text: q[0], author: q[1], image: '/images/quotes/' + q[2] + '.jpg', demo: true });\n  }\n};\n","utils/api.js":"/* ============================================================\n * API 门面（页面唯一入口，保持函数签名稳定）\n * 真正的实现在 utils/domains/*（业务策略）与 utils/adapters/*（云端/演示）。\n * - 云端：wx.cloud.callFunction，身份由云端上下文提供\n * - 演示：utils/adapters/demo.js，结果带 demo 标记\n * ============================================================ */\nconst cfg = require('./config');\nconst { callCloud } = require('./transport');\nconst profile = require('./domains/profile');\nconst chat = require('./domains/chat');\nconst report = require('./domains/report');\nconst content = require('./domains/content');\nconst companion = require('./domains/companion');\nconst moodDomain = require('./domains/mood');\n\n/* HTTP 网关已弃用；保留空实现让旧调用明确失败，而不是静默走错通道 */\nfunction request() {\n  return Promise.reject(new Error('HTTP 网关已弃用，请走云函数通道'));\n}\nfunction rawRequest() {\n  return Promise.reject(new Error('HTTP 网关已弃用，请走云函数通道'));\n}\n\n/* ---------- 建档 / 启动同步 ---------- */\nconst fetchOnboardQuestions = profile.questions;\nconst submitOnboard = profile.save;\nconst syncCloud = profile.sync;\n\n/* ---------- 对话 ---------- */\nconst fetchChatScript = chat.opening;\nconst sendChatMessage = chat.send;\nconst CRISIS_WORDS = chat.CRISIS_WORDS;\nconst seedChat = chat.seed;\nconst resetChat = chat.reset;\n\n/* ---------- 梳理报告 ---------- */\nconst fetchPrediagQuestions = report.questions;\nconst submitPrediagAnswers = report.generate;\n\n/* ---------- 陪伴师（本期演示名单） ---------- */\nconst fetchCounselors = companion.list;\nconst fetchCounselorDetail = companion.detail;\n\n/* ---------- 首页金句 ---------- */\nconst fetchDailyQuote = content.dailyQuote;\n\n/* ---------- 支付（本期无商户号，保持演示） ---------- */\nfunction createOrder() {\n  return new Promise(r => setTimeout(() => r({ orderId: 'demo-' + Date.now(), payParams: null, demo: true }), 300));\n}\n\n/* ---------- 删除云端档案（用户主动清除） ---------- */\nfunction deleteProfile() {\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return Promise.resolve({ ok: true, local: true });\n  return callCloud('xixiData', { action: 'delete' }).catch(() => ({ ok: false }));\n}\n\n/* ---------- 心情打卡：本地记录为准，云端备份 ---------- */\nfunction saveMood(moodIndex) {\n  return moodDomain.save(moodIndex).then(() => undefined);\n}\n\nmodule.exports = {\n  USE_MOCK: cfg.USE_MOCK,\n  USE_CLOUD: cfg.USE_CLOUD,\n  BASE_URL: '',\n  request,\n  rawRequest,\n  callCloud,\n  syncCloud,\n  fetchOnboardQuestions,\n  submitOnboard,\n  fetchChatScript,\n  sendChatMessage,\n  CRISIS_WORDS,\n  seedChat,\n  resetChat,\n  fetchPrediagQuestions,\n  submitPrediagAnswers,\n  fetchCounselors,\n  fetchCounselorDetail,\n  fetchDailyQuote,\n  createOrder,\n  saveMood,\n  deleteProfile\n};\n","utils/config.js":"/* 运行配置：演示/云端开关与超时。页面不直接读这里。 */\nmodule.exports = {\n  USE_MOCK: false,        // 演示数据总开关（离线排查用）\n  USE_CLOUD: true,        // 云端适配器总开关\n  CLOUD_TIMEOUT: 8000,    // 普通云函数调用上限\n  LLM_TIMEOUT: 25000      // 模型类调用（聊天/报告）\n};\n","utils/domains/chat.js":"/* 对话域：开场、发送、危机策略、上下文。页面只拿到 {reply, crisis}。 */\nconst cfg = require('../config');\nconst cloud = require('../adapters/cloud');\nconst demo = require('../adapters/demo');\nconst { delay } = require('../transport');\n\n/* 与服务端词表保持同族；前端这层是「先拦」，不依赖网络 */\nconst CRISIS_WORDS = ['想死', '活不下去', '不想活', '自杀', '家暴', '打死我', '割腕', '轻生', '安眠药', '跳楼', '自残', '一了百了', '结束生命'];\nconst CRISIS_REPLY = '我听到你说的这些，我很在意你现在的状态。有些话电话里说会更踏实：24 小时心理援助热线 400-161-9995，紧急情况请拨 110 / 120。\\n\\n你不需要一个人扛着，也可以联系身边信得过的人。我在这里，陪你把这一刻先过去。';\n\nconst MAX_TURNS = 16;\nlet history = [];\n\nfunction greeting() {\n  const h = new Date().getHours();\n  const when = h < 6 ? '夜深了' : h < 12 ? '上午好' : h < 18 ? '下午好' : '晚上好';\n  return when + '，{name}。我在这里，今天过得怎么样？慢慢说，不着急。';\n}\n\nfunction opening() {\n  return delay(100, [{ role: 'ai', text: greeting() }]);\n}\n\nfunction isCrisis(text) {\n  return CRISIS_WORDS.some(w => text.indexOf(w) >= 0);\n}\n\nfunction send(text) {\n  const nickname = require('../../stores/user').get('nickname') || '';\n  if (isCrisis(text)) {\n    history.push({ role: 'user', content: text });\n    return delay(300, { reply: CRISIS_REPLY, crisis: true });\n  }\n  history.push({ role: 'user', content: text });\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return demo.chatReply();\n\n  const payload = { text: text, history: history.slice(-MAX_TURNS), name: nickname, moods: require('./mood').recentNames(7) };\n  return cloud.chat(payload).then(res => {\n    const reply = res.reply || demo.CHAT_REPLIES[0];\n    history.push({ role: 'assistant', content: reply });\n    if (history.length > MAX_TURNS * 2) history = history.slice(-MAX_TURNS * 2);\n    return { reply: reply, crisis: !!res.crisis };\n  }).catch(() => {\n    /* 模型不可用/超配额/超时：回落本地回复池；兜底文案不进上下文 */\n    return { reply: demo.CHAT_REPLIES[Math.floor(Math.random() * demo.CHAT_REPLIES.length)], offline: true };\n  });\n}\n\nfunction reset() { history = []; }\n\n/* 从本地会话记录恢复上下文，保证「发给云端的历史」与用户看到的一致 */\nfunction seed(messages) {\n  history = (Array.isArray(messages) ? messages : [])\n    .filter(m => m && m.text && (m.role === 'user' || m.role === 'ai' || m.role === 'me'))\n    .map(m => ({ role: (m.role === 'me' || m.role === 'user') ? 'user' : 'assistant', content: m.text }))\n    .slice(-32);\n  return history.slice();\n}\n\nfunction transcript() { return history.slice(); }\n\nmodule.exports = { CRISIS_WORDS, opening, send, reset, seed, transcript };\n","utils/domains/companion.js":"/* 陪伴师域：本期只有演示名单。demo 为一等字段，页面据此展示标识。 */\nconst demo = require('../adapters/demo');\n\nfunction list() {\n  return demo.companions();\n}\n\nfunction detail(id) {\n  return demo.companionDetail(id);\n}\n\nmodule.exports = { list, detail };\n","utils/domains/content.js":"/* 内容域：每日金句与内容表。云端优先、包内兜底；远端图仅接受 https。 */\nconst cfg = require('../config');\nconst cloud = require('../adapters/cloud');\nconst demo = require('../adapters/demo');\n\nfunction dayOfYear() {\n  return Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 864e5);\n}\n\nfunction dailyQuote() {\n  const day = dayOfYear();\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return demo.quote(day);\n  return cloud.content().then(res => {\n    const quotes = (res && res.data && res.data.quotes) || [];\n    if (!quotes.length) return demo.quote(day);\n    const item = quotes[day % quotes.length];\n    const remote = (item && (item.img || item.image)) || '';\n    /* 动态拼接图集：q1..q8（gate 的 check-assets DYNAMIC_SETS 按此断言成员存在——改 8 要两处同步） */\n    const local = '/images/quotes/q' + ((day % 8) + 1) + '.jpg';\n    return {\n      text: item.text,\n      author: item.author || '',\n      image: /^https:\\/\\//.test(remote) ? remote : local,\n      source: item.source || ''\n    };\n  }).catch(() => demo.quote(day));\n}\n\n/* 生理期关怀提醒文案：admin「远程开关与运营文案」的 remote.careTip（票 61 接线）；\n * 未配置/云端不可达返回空串，页面用包内兜底文案 */\nfunction careTip() {\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return Promise.resolve('');\n  return cloud.content().then(res => {\n    const r = (res && res.data && res.data.remote) || {};\n    return typeof r.careTip === 'string' ? r.careTip : '';\n  }).catch(() => '');\n}\n\n/* 运营公告：admin「远程开关与运营文案」的 remote.announcement（票 65 最小承载）；\n * 空串=不展示。与 careTip 同源同失败语义 */\nfunction announcement() {\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return Promise.resolve('');\n  return cloud.content().then(res => {\n    const r = (res && res.data && res.data.remote) || {};\n    return typeof r.announcement === 'string' ? r.announcement : '';\n  }).catch(() => '');\n}\n\nmodule.exports = { dailyQuote, dayOfYear, careTip, announcement };\n","utils/domains/mood.js":"/* 心情域：本地记录为准，云端按 openid 备份。\n * 记录数组 xixi_moods = [{date:'YYYY-MM-DD', mood:0..4}]，同日覆盖。 */\nconst cfg = require('../config');\nconst { callCloud } = require('../transport');\n\nconst MAX = 400;\n\nfunction pad2(n) { return ('0' + n).slice(-2); }\nfunction dateOf(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }\n\nfunction read() {\n  try {\n    const list = wx.getStorageSync('xixi_moods');\n    return Array.isArray(list) ? list : [];\n  } catch (e) {\n    return [];\n  }\n}\n\nfunction write(list) {\n  try { wx.setStorageSync('xixi_moods', list.slice(-MAX)); } catch (e) {}\n}\n\n/* 同日覆盖、按日期升序 */\nfunction merge(list, entry) {\n  const map = {};\n  list.forEach(it => { if (it && it.date) map[it.date] = it.mood; });\n  map[entry.date] = entry.mood;\n  return Object.keys(map).sort().slice(-MAX).map(date => ({ date: date, mood: map[date] }));\n}\n\nfunction save(index, when) {\n  const d = when || new Date();\n  const date = dateOf(d);\n  write(merge(read(), { date: date, mood: index }));\n  /* 旧键：页面即时显示用（月/日下标与历史一致） */\n  try {\n    wx.setStorageSync('xixi_mood_' + d.getFullYear() + '_' + d.getMonth() + '_' + d.getDate(), index);\n  } catch (e) {}\n\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return Promise.resolve({ local: true });\n  const payload = { action: 'push', payload: { moods: [{ date: date, mood: index }] } };\n  const ts = () => {\n    try { return Number(wx.getStorageSync('xixi_server_ts')) || 0; } catch (e) { return 0; }\n  };\n  const push = (baseTs) => callCloud('xixiData', Object.assign({ baseTs: baseTs }, payload));\n  return push(ts())\n    .then(res => {\n      try { wx.setStorageSync('xixi_server_ts', Number(res.serverTs) || Date.now()); } catch (e) {}\n      return { synced: true };\n    })\n    .catch(err => {\n      if (err && err.code === 'CONFLICT') {\n        /* 先拉最新再写一次；拉取会把云端列表盖回本地，所以要把刚写的这条合回去 */\n        const entry = { date: date, mood: index };\n        return require('./profile').sync().then(() => {\n          write(merge(read(), entry));\n          return push(ts());\n        }).then(() => ({ synced: true })).catch(() => ({ synced: false }));\n      }\n      return { synced: false };\n    });\n}\n\n/* 最近 n 条心情的中文名，供对话/报告做上下文 */\nfunction recentNames(n) {\n  const NAMES = require('../mood').NAMES;\n  return read().slice(-(n || 7)).map(it => NAMES[Number(it.mood)]).filter(x => typeof x === 'string');\n}\n\nmodule.exports = { read, write, merge, save, dateOf, recentNames };\n","utils/domains/profile.js":"/* 档案域：问卷答案、称呼、跨设备同步。写云端失败不阻断本地流程。 */\nconst cfg = require('../config');\nconst cloud = require('../adapters/cloud');\nconst demo = require('../adapters/demo');\nconst { delay } = require('../transport');\n\nfunction nicknameFrom(answers) {\n  const raw = answers && answers[4];\n  const given = Array.isArray(raw) ? raw[0] : raw;\n  return given || require('../../stores/user').get('nickname') || '小美';\n}\n\nfunction save(answers) {\n  const nickname = nicknameFrom(answers);\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return delay(200, { userId: 'mock-user', nickname: nickname });\n  const profile = { answers: answers };\n  const raw = answers && answers[4];\n  const given = Array.isArray(raw) ? raw[0] : raw;\n  if (given) profile.nickname = given;\n  const attempt = (ts) => cloud.saveProfile(profile, ts);\n  return attempt(baseTs())\n    .then(res => {\n      try { wx.setStorageSync('xixi_server_ts', Number(res.serverTs) || Date.now()); } catch (e) {}\n      return { userId: res.openid || '', nickname: nickname };\n    })\n    .catch(err => {\n      /* 并发冲突：先拉最新再写一次；仍失败则本地继续 */\n      if (err && err.code === 'CONFLICT') {\n        return sync().then(() => attempt(baseTs())).then(() => ({ userId: '', nickname: nickname }))\n          .catch(() => ({ userId: '', nickname: nickname, offline: true }));\n      }\n      return { userId: '', nickname: nickname, offline: true };\n    });\n}\n\n/* 启动同步：拉回称呼、答卷与心情历史；失败静默 */\nfunction sync() {\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return Promise.resolve(null);\n  return cloud.pull().then(res => {\n    const d = (res && res.data) || {};\n    if (Array.isArray(d.moods) && d.moods.length) {\n      try { wx.setStorageSync('xixi_moods', d.moods); } catch (e) {}\n    }\n    if (d.profile) {\n      const user = require('../../stores/user');\n      const patch = {};\n      if (d.profile.nickname) patch.nickname = d.profile.nickname;\n      if (d.profile.answers) patch.obAnswers = d.profile.answers;\n      Object.keys(patch).length && user.set(patch);\n    }\n    try { wx.setStorageSync('xixi_server_ts', Number(d.serverTs) || 0); } catch (e) {}\n    return d;\n  }).catch(() => null);\n}\n\nfunction baseTs() {\n  try { return Number(wx.getStorageSync('xixi_server_ts')) || 0; } catch (e) { return 0; }\n}\n\nmodule.exports = { save, sync, questions: demo.onboardQuestions, nicknameFrom };\n","utils/domains/report.js":"/* 报告域：题目（静态）、生成（云端）、形状适配、失败态。\n * 失败时返回 { report:null, failed:true }，绝不返回示例报告。 */\nconst cfg = require('../config');\nconst cloud = require('../adapters/cloud');\nconst demo = require('../adapters/demo');\n\nfunction questions() { return demo.prediagQuestions(); }\n\n/* 云端：urgency 为 18~92 数值 + urgencyText；页面要 { level: 0~1, label } */\nfunction toReport(r) {\n  if (!r || !Array.isArray(r.emotions) || !r.conflict) return null;\n  const n = Number(r.urgency) || 45;\n  const label = r.urgencyText || (n >= 70 ? '较高 · 建议尽快联系' : n >= 40 ? '中度 · 建议尽快' : '轻度 · 可先自助');\n  return {\n    emotions: r.emotions.slice(0, 3),\n    conflict: r.conflict,\n    goal: r.goal || '先稳定当下情绪，再决定下一步。',\n    urgency: { level: Math.max(0.18, Math.min(0.92, n / 100)), label: label },\n    direction: r.direction || ''\n  };\n}\n\nfunction generate(answers) {\n  if (cfg.USE_MOCK || !cfg.USE_CLOUD) return demo.report();\n  return cloud.report(answers, { moods: require('./mood').recentNames(14) }).then(res => {\n    const report = toReport(res.report);\n    return report ? { report: report } : { report: null, failed: true };\n  }).catch(() => ({ report: null, failed: true }));\n}\n\nmodule.exports = { questions, generate, toReport };\n","utils/mood.js":"/* 心情数据：表情脸 SVG data-uri + 月历计算（home / moodcal 共用） */\nconst GCM = { '平静':'#DCC6C0','委屈':'#C7D0DA','焦虑':'#E4D6BC','烦躁':'#DFBCB2','难过':'#CDC2D4' };\nconst FACE = {\n  '平静':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#DCC6C0\"/><path d=\"M7.6 10.4q1.2-1.4 2.5 0M13.9 10.4q1.2-1.4 2.5 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M8.7 14.2q3.3 2.4 6.6 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>',\n  '委屈':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#C7D0DA\"/><path d=\"M7.3 9.7l2.5-1.5M16.7 9.7l-2.5-1.5\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"8.8\" cy=\"11.8\" r=\".95\" fill=\"#fff\"/><circle cx=\"15.2\" cy=\"11.8\" r=\".95\" fill=\"#fff\"/><path d=\"M9.4 15.9q2.6-1.9 5.2 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>',\n  '焦虑':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#E4D6BC\"/><circle cx=\"8.6\" cy=\"10.6\" r=\"1.25\" fill=\"#fff\"/><circle cx=\"15.4\" cy=\"10.6\" r=\"1.25\" fill=\"#fff\"/><path d=\"M7.6 15.2l1.4-1.3 1.5 1.3 1.5-1.3 1.5 1.3 1.4-1.3\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>',\n  '烦躁':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#DFBCB2\"/><path d=\"M7 9.4l3 1.5M17 9.4l-3 1.5\" stroke=\"#fff\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><circle cx=\"9\" cy=\"12.1\" r=\".95\" fill=\"#fff\"/><circle cx=\"15\" cy=\"12.1\" r=\".95\" fill=\"#fff\"/><path d=\"M9 16.4q3-2.3 6 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>',\n  '难过':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#CDC2D4\"/><path d=\"M7.9 10.6q1.1-1.2 2.3 0M13.8 10.6q1.1-1.2 2.3 0\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M8.1 13.4c-1.1 1.5-.9 2.8.3 3.1s2.1-.8 1.3-2.2z\" fill=\"#fff\"/><path d=\"M10.2 17.1q2.2-1.7 4.4 0\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\"/>'\n};\nconst NAMES = Object.keys(GCM);\n\nfunction b64(s) {\n  const CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';\n  let out = '', buf = '';\n  for (let i = 0; i < s.length; i++) {\n    buf += String.fromCharCode(s.charCodeAt(i));\n    while (buf.length >= 3) {\n      const b = [buf.charCodeAt(0), buf.charCodeAt(1), buf.charCodeAt(2)];\n      out += CH[b[0] >> 2] + CH[((b[0] & 3) << 4) | (b[1] >> 4)] + CH[((b[1] & 15) << 2) | (b[2] >> 6)] + CH[b[2] & 63];\n      buf = buf.slice(3);\n    }\n  }\n  if (buf.length === 1) out += CH[buf.charCodeAt(0) >> 2] + CH[(buf.charCodeAt(0) & 3) << 4] + '==';\n  else if (buf.length === 2) {\n    const b = [buf.charCodeAt(0), buf.charCodeAt(1)];\n    out += CH[b[0] >> 2] + CH[((b[0] & 3) << 4) | (b[1] >> 4)] + CH[(b[1] & 15) << 2] + '=';\n  }\n  return out;\n}\nfunction svgUri(svg) {\n  /* base64 无需引号：WXML style 属性内双引号会截断 */\n  return 'url(data:image/svg+xml;base64,' + b64(svg) + ')';\n}\nfunction faceUri(name) {\n  return svgUri('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">' + FACE[name] + '</svg>');\n}\nfunction plusUri() {\n  return svgUri('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#A9939E\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>');\n}\n/* ---------- 真实记录读取 ---------- */\nfunction pad2(n) { return ('0' + n).slice(-2); }\nfunction dateKey(y, m, d) { return y + '-' + pad2(m + 1) + '-' + pad2(d); }\nfunction moodKey() {\n  const now = new Date();\n  return 'xixi_mood_' + now.getFullYear() + '_' + now.getMonth() + '_' + now.getDate();\n}\n\n/* date → 心情下标。来源：云端回填的 xixi_moods 数组 + 当天本地即时值 */\nfunction records() {\n  const map = {};\n  try {\n    (wx.getStorageSync('xixi_moods') || []).forEach(it => {\n      if (it && it.date) map[it.date] = Number(it.mood);\n    });\n  } catch (e) {}\n  return map;\n}\n\nfunction todayValue(map) {\n  const now = new Date();\n  let v = null;\n  try { v = wx.getStorageSync(moodKey()); } catch (e) {}\n  if (v !== '' && v !== null && v !== undefined) {\n    map[dateKey(now.getFullYear(), now.getMonth(), now.getDate())] = Number(v);\n  }\n  return map;\n}\n\n/* 连续打卡天数：今天没打不打断，从昨天继续数 */\nfunction streak() {\n  const map = todayValue(records());\n  let n = 0;\n  for (let i = 0; i < 400; i++) {\n    const d = new Date();\n    d.setDate(d.getDate() - i);\n    const k = dateKey(d.getFullYear(), d.getMonth(), d.getDate());\n    if (map[k] !== undefined) n++;\n    else if (i === 0) continue;\n    else break;\n  }\n  return n;\n}\n\n/* 当月日历：只渲染真实记录，无记录为空白 */\nfunction calendar() {\n  const now = new Date(), y = now.getFullYear(), mo = now.getMonth(), today = now.getDate();\n  const dim = new Date(y, mo + 1, 0).getDate(), first = (new Date(y, mo, 1).getDay() + 6) % 7;\n  const map = todayValue(records());\n  const hist = {};\n  for (let d = 1; d <= today; d++) {\n    const v = map[dateKey(y, mo, d)];\n    hist[d] = v === undefined ? null : v;\n  }\n  const cells = [];\n  for (let i = 0; i < first; i++) cells.push({ fut: true, pad: true });\n  for (let d = 1; d <= dim; d++) {\n    const mi = d <= today ? hist[d] : null;\n    cells.push({ d, mi, today: d === today, fut: d > today });\n  }\n  const dow = (now.getDay() + 6) % 7, WD = ['一','二','三','四','五','六','日'];\n  const week = [];\n  for (let i = 0; i < 7; i++) {\n    const d = today - dow + i;\n    const inMonth = d >= 1 && d <= dim;\n    const mi = inMonth ? map[dateKey(y, mo, d)] : undefined;\n    week.push({\n      d: inMonth ? d : '',\n      label: WD[i] + (inMonth ? ' ' + d : ''),\n      today: i === dow,\n      fut: !inMonth || d > today,\n      mi: mi === undefined ? null : mi,\n      name: mi === undefined ? null : NAMES[mi]\n    });\n  }\n  const from = Math.max(1, today - dow), to = Math.min(dim, today - dow + 6);\n  return {\n    today, month: mo + 1, hist,\n    ym: (mo + 1) + '月 · 星期' + '日一二三四五六'[now.getDay()],\n    monthTitle: (mo + 1) + '月 · 心情月历',\n    weekCap: (mo + 1) + '月' + from + '日 – ' + (mo + 1) + '月' + to + '日',\n    cells, week\n  };\n}\nmodule.exports = { GCM, FACE, NAMES, faceUri, plusUri, calendar, moodKey, records, streak, dateKey };\n","utils/transport.js":"/* 传输层：只管把一次调用发出去并归一错误，不含业务判断。 */\nconst cfg = require('./config');\n\nfunction cloudError(code, detail) {\n  const e = new Error(code + (detail ? ': ' + detail : ''));\n  e.code = code;\n  return e;\n}\n\nfunction callCloud(name, data, timeout) {\n  const limit = timeout || cfg.CLOUD_TIMEOUT;\n  return new Promise((resolve, reject) => {\n    if (!wx.cloud || !wx.cloud.callFunction) {\n      reject(cloudError('CLOUD_UNAVAILABLE'));\n      return;\n    }\n    let settled = false;\n    const timer = setTimeout(() => {\n      if (settled) return;\n      settled = true;\n      reject(cloudError('CLOUD_TIMEOUT'));\n    }, limit);\n    const finish = (fn, v) => {\n      if (settled) return;\n      settled = true;\n      clearTimeout(timer);\n      fn(v);\n    };\n    try {\n      wx.cloud.callFunction({\n        name: name,\n        data: data || {},\n        success(res) {\n          const r = (res && res.result) || {};\n          if (r.ok === false) finish(reject, cloudError(r.err || 'CLOUD_FAILED'));\n          else finish(resolve, r);\n        },\n        fail(e) {\n          finish(reject, cloudError('CLOUD_FAILED', (e && e.errMsg) || ''));\n        }\n      });\n    } catch (e) {\n      finish(reject, cloudError('CLOUD_FAILED', e.message));\n    }\n  });\n}\n\nfunction delay(ms, val) {\n  return new Promise(r => setTimeout(() => r(val), ms));\n}\n\nmodule.exports = { callCloud, delay, cloudError };\n","utils/ui.js":"/* 设备框架度量：状态栏、导航带、底部安全区。\n * 小程序里 env(safe-area-inset-*) 在部分机型恒为 0，顶部必须以设备实测值为准。 */\n\nfunction windowInfo() {\n  try {\n    if (wx.getWindowInfo) return wx.getWindowInfo();\n  } catch (e) {}\n  try {\n    return wx.getSystemInfoSync();\n  } catch (e) {\n    return {};\n  }\n}\n\nfunction menuRect() {\n  try {\n    const r = wx.getMenuButtonBoundingClientRect();\n    if (r && r.height) return r;\n  } catch (e) {}\n  return null;\n}\n\n/* top = 状态栏 + 导航带（与胶囊同高）\n * nav = 导航带高度（无胶囊时回落 44）\n * bottom = Home 指示条区域\n * contentTop = 内容区起点（导航带下沿 + 12px 呼吸） */\nfunction frame() {\n  const w = windowInfo();\n  const statusBar = Math.round(Number(w.statusBarHeight) || 20);\n  const r = menuRect();\n  const nav = r && r.top ? Math.round((r.top - statusBar) * 2 + r.height) : 44;\n  const top = statusBar + nav;\n  let bottom = 0;\n  if (w.safeArea && (w.screenHeight || w.windowHeight)) {\n    bottom = Math.max(0, Math.round((w.screenHeight || w.windowHeight) - w.safeArea.bottom));\n  }\n  return { statusBar, nav, top, contentTop: top + 12, bottom, windowHeight: Math.round(w.windowHeight || 0) };\n}\n\nmodule.exports = { frame };\n"};